import { Agent, GameEngine } from "../game";
import { GridSystem } from "../systems/grid";
import { HexUtils } from "../utils";
import { UNIT_BODY_OFFSET, UNIT_HOVER_OFFSET, UNIT_VISUAL_HEIGHT, UNIT_SCALE } from "../../constants";

export interface Point3D {
    x: number;
    y: number;
    z: number;
}

export class VisualMath {
    public static readonly Z_LAYERS = {
        TERRAIN: 0,
        HAZARD: 3,
        OVERLAY: 5,
        SHADOW: 8,
        UNIT_FEET: 0
    };

    /**
     * SSOT: 唯一等角視覺 Y 軸投影入口
     */
    public static getIsoVisualY(y: number, z: number, extraOffset: number = 0): number {
        return y - z + extraOffset;
    }

    public static applyLayerBias(visualY: number, layer: keyof typeof VisualMath.Z_LAYERS): number {
        return visualY - this.Z_LAYERS[layer];
    }

    public static getVisualBodyCenterY(surfaceY: number, z: number): number {
        return surfaceY - z - UNIT_BODY_OFFSET - UNIT_HOVER_OFFSET;
    }

    public static getUnitAnchor(agent: Agent, engine: GameEngine, grid: GridSystem | null = null): Point3D {
        const terrainH = grid 
            ? grid.getTerrainHeight(agent.q, agent.r, engine) 
            : engine.map.getTerrainHeight(agent.q, agent.r);
        const chestHeight = (UNIT_VISUAL_HEIGHT * 0.45) * UNIT_SCALE;
        const z = terrainH + agent.physics.z + UNIT_BODY_OFFSET + UNIT_HOVER_OFFSET + chestHeight;
        return { x: agent.px, y: agent.py, z: z };
    }

    public static resolveTargetPoint(targetId: string, engine: GameEngine): Point3D {
        if (!targetId) return { x: 0, y: 0, z: -9999 };
        const agent = engine.agents.find(a => a.id === targetId);
        if (agent) return this.getUnitAnchor(agent, engine);
        if (targetId.startsWith("ground-")) {
            const parts = targetId.split("-")[1].split(",");
            if (parts.length === 2) {
                const q = parseInt(parts[0]);
                const r = parseInt(parts[1]);
                const p = HexUtils.toPx(q, r, engine.mapConfig);
                const h = engine.map.getTerrainHeight(q, r);
                return { x: p.x, y: p.y, z: h + 2 };
            }
        }
        return { x: 0, y: 0, z: -9999 };
    }
}

import { Agent } from "../game";
import { HUD_BAR_OFFSET } from "../../constants";
import { HexUtils, MapConfig } from "../utils";
import { HUDSystem } from "../systems/hud";
import { VisualMath } from "../math/VisualMath";
import { BarPainter } from "./hud/BarPainter";
import { GaugePainter } from "./hud/GaugePainter";
import { TextPainter } from "./hud/TextPainter";

export class HUDRenderer {
    public draw(ctx: CanvasRenderingContext2D, hud: HUDSystem, agents: Agent[], getTerrainHeight: (q: number, r: number) => number, mapConfig: MapConfig, highlight: Agent | null, time: number) {
        agents.forEach(a => {
            if (a.hp <= 0 || a.spawnTimer > 0) return;

            let h = 0;
            if (a.isMoving && a.path.length > 0) {
                const startH = getTerrainHeight(a.q, a.r);
                const endH = getTerrainHeight(a.path[0].q, a.path[0].r);
                h = HexUtils.lerp(startH, endH, a.moveProgress);
            } else {
                const vHex = HexUtils.fromPx(a.px, a.py, mapConfig);
                h = getTerrainHeight(vHex.q, vHex.r);
            }

            // 強制使用 SSOT 坐標投影
            const visualGroundY = VisualMath.getIsoVisualY(a.py, h);
            const physicsOffsetZ = a.physics.y - a.physics.z; 
            const anchorY = visualGroundY + physicsOffsetZ - HUD_BAR_OFFSET;
            const headX = a.px + a.physics.x;

            const isSelected = (a === highlight);
            BarPainter.drawUnitBars(ctx, headX, anchorY, a, isSelected);
            GaugePainter.drawUnitStatusGauges(ctx, a, headX, anchorY);
        });
        TextPainter.drawFloatingText(ctx, hud);
    }
}

import { GameEngine, Agent } from "../../game";
import { HexUtils } from "../../utils";
import { Hex } from "../../../types";
import { BLOCK_HEIGHT, HEX_SIZE } from "../../../constants";
import { GridCache } from "./GridCache";
import { VisualMath } from "../../math/VisualMath";

export class GridSpatial {
    public static getValidHexesInRange(centerQ: number, centerR: number, radius: number, engine: GameEngine): Hex[] {
        const candidates = HexUtils.range({q: centerQ, r: centerR}, radius);
        return candidates.filter(hex => engine.map.isValid(hex.q, hex.r));
    }

    public static getHexAtWorldPoint(wx: number, wy: number, engine: GameEngine, cache: GridCache): Hex | null {
        cache.ensure(engine);
        const maxHeight = 300; 
        const step = BLOCK_HEIGHT;
        let bestHex: Hex | null = null;
        let bestH = -999;

        for (let h = 0; h <= maxHeight; h += step) {
            const testY = wy + h; 
            const rounded = HexUtils.fromPx(wx, testY, engine.mapConfig);
            const tile = cache.tileMap.get(HexUtils.key(rounded));

            if (tile) {
                // 使用 VisualMath 驗證視覺頂面
                const visualTopY = VisualMath.getIsoVisualY(tile.py, tile.h);
                const dx = Math.abs(wx - tile.px);
                const dy = Math.abs(wy - visualTopY);

                if (dx < HEX_SIZE * 0.9 && dy < HEX_SIZE * 0.6) {
                    if (tile.h >= bestH) {
                        bestHex = rounded;
                        bestH = tile.h;
                    }
                }
            }
        }
        return bestHex;
    }

    public static getOccludedAgents(engine: GameEngine): Agent[] {
        const occluded: Agent[] = [];
        for (const a of engine.agents) {
            if (a.hp <= 0 && a.fullyDead) continue;
            const uTerrainH = engine.map.getTerrainHeight(a.q, a.r);
            const neighbors = HexUtils.neighbors({q: a.q, r: a.r});
            const currentSort = a.q + a.r;
            for (const n of neighbors) {
                if ((n.q + n.r) > currentSort) {
                    if (engine.mapKeys.has(HexUtils.key(n))) {
                        if (engine.map.getTerrainHeight(n.q, n.r) > uTerrainH + 20) {
                            occluded.push(a);
                            break;
                        }
                    }
                }
            }
        }
        return occluded;
    }
}

import { ISO_SCALE_Y, HEX_SIZE } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";
import { VisualMath } from "../../math/VisualMath";

const PEDESTAL_DEPTH = 30; 
const EXPANSION_BIAS = 0.6;

export const TerrainRenderer = {
    drawBlock(ctx: CanvasRenderingContext2D, x: number, y: number, size: number, height: number, theme: any, type: string, globalTime: number, layout: HexLayout) {
        const drawX = Math.floor(x);
        const isFloatingBiome = type === 'VOID' || type === 'MAGMA';
        let floatOffset = 0;
        if (isFloatingBiome) floatOffset = Math.sin(globalTime * 1.5 + (x * 0.01) + (y * 0.01)) * 4;

        // 強制遵照 SSOT 投影公式，將呼吸動畫作為 Z 軸偏移的一部分
        const visualTopY = VisualMath.getIsoVisualY(0, height, floatOffset);
        const drawY = Math.floor(y);
        const r = size + EXPANSION_BIAS;
        const vertices = HexGeometry.getVertices(r, true, layout); 

        ctx.save();
        ctx.translate(drawX, drawY);

        const drawFace = (idx1: number, idx2: number, color: string, isLightSide: boolean) => {
            const v1 = vertices[idx1], v2 = vertices[idx2];
            const grad = ctx.createLinearGradient(0, visualTopY, 0, PEDESTAL_DEPTH);
            grad.addColorStop(0, color);
            grad.addColorStop(1, isLightSide ? theme.sideDark : '#020617');
            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y + visualTopY);
            ctx.lineTo(v2.x, v2.y + visualTopY);
            ctx.lineTo(v2.x, v2.y + PEDESTAL_DEPTH);
            ctx.lineTo(v1.x, v1.y + PEDESTAL_DEPTH);
            ctx.closePath();
            ctx.fill();
        };

        if (layout === 'FLAT') {
            drawFace(1, 0, theme.sideDark, false);
            drawFace(2, 1, theme.sideLight, true);
            drawFace(3, 2, theme.sideDark, false);
        } else {
            drawFace(1, 0, theme.sideDark, false);
            drawFace(2, 1, theme.sideLight, true);
        }

        ctx.translate(0, visualTopY);
        const topGrad = ctx.createLinearGradient(-r, -r, r, r);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.3, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 
        ctx.fillStyle = topGrad;
        ctx.beginPath();
        ctx.moveTo(vertices[0].x, vertices[0].y);
        for (let i = 1; i < 6; i++) ctx.lineTo(vertices[i].x, vertices[i].y);
        ctx.closePath();
        ctx.fill();
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.5; ctx.globalAlpha = 0.6; ctx.stroke();
        if (type === 'MAGMA') SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', globalTime, 1.0, layout);
        ctx.restore();
    },

    drawTerrainDetail(ctx: CanvasRenderingContext2D, baseX: number, baseY: number, height: number, type: string, detailColor: string, q: number, r: number, globalTime: number = 0, layout: HexLayout = 'FLAT', theme: any) {
        const isFloatingBiome = type === 'VOID' || type === 'MAGMA';
        let floatOffset = 0;
        if (isFloatingBiome) floatOffset = Math.sin(globalTime * 1.5 + (baseX * 0.01) + (baseY * 0.01)) * 4;

        const visualY = VisualMath.getIsoVisualY(baseY, height, floatOffset);
        if (type === 'FOREST') SurfacePainter.drawGrass(ctx, baseX, visualY, theme.top || '#14532d', 5, globalTime);
        else if (type === 'ICE') SurfacePainter.drawIceSheen(ctx, baseX, visualY, HEX_SIZE, globalTime, layout);
        else if (type === 'DESERT') SurfacePainter.drawSandRipples(ctx, baseX, visualY, HEX_SIZE, theme.sideDark || '#92400e');
        else if (type === 'VOID') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
        }
    }
};

