import { SceneTheme } from "../../types";
import { HEX_SIZE } from "../../constants";
import { AssetManager } from "../assets";
import { MapConfig } from "../utils";
import { createCanvas } from "../graphics/CanvasUtils";
import { VFXFactory } from "../graphics/VFXFactory";
import { VisualMath } from "../math/VisualMath";

export class BackgroundRenderer {
    private staticCache: HTMLCanvasElement | null = null;
    private lastSceneId: string = "";
    private lastWidth: number = 0;
    private lastHeight: number = 0;

    public draw(ctx: CanvasRenderingContext2D, width: number, height: number, scene: SceneTheme, mapConfig: MapConfig, globalTime: number): void {
        if (!this.staticCache || this.lastSceneId !== scene.id || this.lastWidth !== width || this.lastHeight !== height) {
            this.updateStaticCache(width, height, scene);
        }
        if (this.staticCache) {
            ctx.drawImage(this.staticCache, 0, 0);
        }
        this.drawDynamicElements(ctx, width, height, scene, mapConfig, globalTime);
    }

    private hexToRgba(hex: string, alpha: number): string {
        const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
        if (!result) return `rgba(0,0,0,${alpha})`;
        return `rgba(${parseInt(result[1], 16)}, ${parseInt(result[2], 16)}, ${parseInt(result[3], 16)}, ${alpha})`;
    }

    private updateStaticCache(w: number, h: number, scene: SceneTheme) {
        if (!this.staticCache) {
            const { canvas } = createCanvas(w, h);
            this.staticCache = canvas;
        } else {
            this.staticCache.width = w;
            this.staticCache.height = h;
        }

        this.lastSceneId = scene.id;
        this.lastWidth = w;
        this.lastHeight = h;

        const ctx = this.staticCache.getContext('2d')!;
        ctx.clearRect(0, 0, w, h);

        const bgGrad = ctx.createLinearGradient(0, 0, 0, h);
        bgGrad.addColorStop(0, scene.background);
        bgGrad.addColorStop(0.4, scene.fogColor); 
        bgGrad.addColorStop(1, scene.horizon); 
        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, w, h);

        if (scene.bgFeature === 'SKY_RIVER') this.drawStaticSkyRiver(ctx, w, h);
        else this.drawStaticStars(ctx, w, h, 150);

        this.drawPerspectiveGrid(ctx, w, h, scene.horizon);

        if (scene.bgFeature === 'DUNES') this.drawStaticDunes(ctx, w, h, scene.horizon, scene.fogColor);
        else this.drawStaticMountains(ctx, w, h, scene.horizon, scene.fogColor);

        // SSOT: Use VisualMath.HORIZON_Y_PCT
        const horizonY = h * VisualMath.HORIZON_Y_PCT;
        const seamHeight = 350; 
        const seamGrad = ctx.createLinearGradient(0, horizonY - seamHeight * 0.6, 0, horizonY + seamHeight * 0.4);

        seamGrad.addColorStop(0, this.hexToRgba(scene.fogColor, 0));
        seamGrad.addColorStop(0.3, this.hexToRgba(scene.fogColor, 0.8));
        seamGrad.addColorStop(0.5, this.hexToRgba(scene.fogColor, 1.0)); 
        seamGrad.addColorStop(0.7, this.hexToRgba(scene.fogColor, 0.8));
        seamGrad.addColorStop(1, this.hexToRgba(scene.fogColor, 0));

        ctx.globalCompositeOperation = 'source-over';
        ctx.fillStyle = seamGrad;
        ctx.fillRect(0, horizonY - seamHeight * 0.6, w, seamHeight);

        const rad = Math.max(w, h);
        const vig = ctx.createRadialGradient(w/2, h/2, rad * 0.4, w/2, h/2, rad * 0.9);
        vig.addColorStop(0, 'rgba(0,0,0,0)');
        vig.addColorStop(1, 'rgba(0,0,0,0.8)');
        ctx.fillStyle = vig;
        ctx.fillRect(0, 0, w, h);
    }

    private drawPerspectiveGrid(ctx: CanvasRenderingContext2D, w: number, h: number, color: string) {
        ctx.save();
        ctx.globalAlpha = 0.15;
        ctx.strokeStyle = color;
        ctx.lineWidth = 1;

        const horizonY = h * VisualMath.HORIZON_Y_PCT;
        const centerX = w * 0.5;

        ctx.beginPath();
        for (let x = -w; x < w * 2; x += 100) {
            ctx.moveTo(x, h);
            ctx.lineTo(centerX + (x - centerX) * 0.1, horizonY);
        }
        ctx.stroke();

        for (let y = h; y > horizonY; y -= (y - horizonY) * 0.1 + 2) {
            const dist = (y - horizonY) / (h - horizonY);
            if (dist < 0.2) continue; 
            ctx.globalAlpha = 0.15 * Math.pow(dist, 0.5);
            ctx.beginPath();
            ctx.moveTo(0, y);
            ctx.lineTo(w, y);
            ctx.stroke();
        }
        ctx.restore();
    }

    private drawStaticStars(ctx: CanvasRenderingContext2D, w: number, h: number, count: number) {
        ctx.fillStyle = '#fff';
        const seed = 123;
        for(let i=0; i<count; i++) {
            const sx = (Math.sin(i * seed) * 0.5 + 0.5) * w;
            const sy = (Math.cos(i * seed * 1.5) * 0.5 + 0.5) * h * 0.7;
            const size = Math.random() * 1.8;
            ctx.globalAlpha = Math.random() * 0.6 + 0.2;
            ctx.beginPath(); ctx.arc(sx, sy, size, 0, Math.PI*2); ctx.fill();
        }
    }

    private drawStaticSkyRiver(ctx: CanvasRenderingContext2D, w: number, h: number) {
        ctx.save();
        const grad = ctx.createLinearGradient(0, 0, w, h * 0.8);
        grad.addColorStop(0, 'rgba(0,0,0,0)');
        grad.addColorStop(0.3, 'rgba(79, 70, 229, 0.15)');
        grad.addColorStop(0.5, 'rgba(124, 58, 237, 0.25)');
        grad.addColorStop(0.7, 'rgba(79, 70, 229, 0.15)');
        grad.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.globalCompositeOperation = 'screen';
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.moveTo(0, h*0.2);
        ctx.quadraticCurveTo(w*0.5, h*0.5, w, h*0.4);
        ctx.lineTo(w, h*0.7);
        ctx.quadraticCurveTo(w*0.5, h*0.8, 0, h*0.5);
        ctx.fill();
        this.drawStaticStars(ctx, w, h, 200);
        ctx.restore();
    }

    private drawStaticMountains(ctx: CanvasRenderingContext2D, w: number, h: number, colorFar: string, colorNear: string) {
        const horizonY = h * VisualMath.HORIZON_Y_PCT;
        const drawLayer = (yOffset: number, color: string, roughness: number, seedOffset: number) => {
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(0, h);
            ctx.lineTo(0, horizonY + yOffset);
            for(let x=0; x<=w; x+=20) {
                const n = Math.sin(x * 0.01 + seedOffset) * Math.cos(x * 0.03) * roughness;
                ctx.lineTo(x, horizonY + yOffset + n);
            }
            ctx.lineTo(w, horizonY + yOffset);
            ctx.lineTo(w, h);
            ctx.fill();
        };
        ctx.globalAlpha = 0.3;
        drawLayer(0, colorFar, 60, 0);
        ctx.globalAlpha = 0.5;
        drawLayer(60, colorNear, 40, 100);
        ctx.globalAlpha = 1.0;
    }

    private drawStaticDunes(ctx: CanvasRenderingContext2D, w: number, h: number, colorFar: string, colorNear: string) {
        const horizonY = h * VisualMath.HORIZON_Y_PCT;
        const drawDune = (yBase: number, color: string, amp: number, freq: number, offset: number) => {
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(0, h);
            ctx.lineTo(0, yBase);
            for(let x=0; x<=w; x+=30) {
                const y = yBase + Math.sin(x * freq + offset) * amp;
                ctx.lineTo(x, y);
            }
            ctx.lineTo(w, yBase);
            ctx.lineTo(w, h);
            ctx.fill();
        };
        ctx.globalAlpha = 0.4;
        drawDune(horizonY + 50, colorFar, 30, 0.005, 0);
        ctx.globalAlpha = 0.6;
        drawDune(horizonY + 150, colorNear, 40, 0.003, 2);
    }

    private drawDynamicElements(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme, mapConfig: MapConfig, t: number) {
        ctx.save();
        ctx.fillStyle = scene.ambientColor;
        for(let i=0; i<50; i++) {
            const speed = (i % 5 + 1) * 10;
            const y = (h + (i * 53) - (t * speed)) % h;
            const x = (w + (i * 97) + Math.sin(t + i)*50) % w;
            const size = Math.sin(t * 2 + i) + 2;
            ctx.globalAlpha = (Math.sin(t + i) * 0.5 + 0.5) * 0.6;
            ctx.beginPath(); ctx.arc(x, y, size, 0, Math.PI*2); ctx.fill();
        }
        const horizonY = h * VisualMath.HORIZON_Y_PCT;
        const pulse = 1.0 + Math.sin(t * 0.5) * 0.1;
        const horizonGrad = ctx.createRadialGradient(w/2, horizonY + 50, w * 0.2, w/2, horizonY + 50, w * 0.8 * pulse);
        horizonGrad.addColorStop(0, scene.horizon);
        horizonGrad.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.3;
        ctx.fillStyle = horizonGrad;
        ctx.fillRect(0, h/2, w, h/2);
        if (scene.bgFeature === 'AURORA') this.drawAurora(ctx, w, h, t);
        else if (scene.bgFeature === 'CANOPY') this.drawCanopyRays(ctx, w, h, t);
        else if (scene.bgFeature === 'HEAT_WAVE') this.drawHeatHaze(ctx, w, h, t, scene.horizon);
        if (scene.textureType === 'DESERT') this.drawSandStorm(ctx, w, h, t, scene.fogColor);
        else this.drawFogLayers(ctx, w, h, scene.fogColor, mapConfig, t);
        ctx.restore();
    }

    private drawAurora(ctx: CanvasRenderingContext2D, w: number, h: number, t: number) {
        ctx.globalCompositeOperation = 'screen';
        const numBands = 3, baseH = h * 0.4;
        for (let i = 0; i < numBands; i++) {
            const speed = t * 0.2 + i;
            ctx.beginPath(); ctx.moveTo(0, baseH);
            for (let x = 0; x <= w; x += 50) {
                const y = baseH + Math.sin(x * 0.005 + speed) * 50 + Math.sin(x * 0.02 - speed) * 20;
                ctx.lineTo(x, y);
            }
            ctx.lineTo(w, 0); ctx.lineTo(0, 0);
            const grad = ctx.createLinearGradient(0, 0, w, 0);
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(0.5, `hsla(170, 80%, 60%, 0.15)`); 
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad; ctx.fill();
        }
    }

    private drawCanopyRays(ctx: CanvasRenderingContext2D, w: number, h: number, t: number) {
        ctx.globalCompositeOperation = 'overlay';
        const raySprite = VFXFactory.getTexture('BEAM', 'rgba(255,255,255,0.1)');
        for (let i = 0; i < 4; i++) {
            const angle = Math.sin(t * 0.2 + i) * 0.1 + 0.6, x = w * (0.2 + i * 0.2) + Math.sin(t * 0.1) * 50;
            ctx.save(); ctx.translate(x, -100); ctx.rotate(angle); ctx.globalAlpha = 0.15 + Math.sin(t * 0.5 + i) * 0.05;
            ctx.drawImage(raySprite, -50, 0, 100, h * 1.5); ctx.restore();
        }
    }

    private drawHeatHaze(ctx: CanvasRenderingContext2D, w: number, h: number, t: number, color: string) {
        const horizonY = h * VisualMath.HORIZON_Y_PCT;
        ctx.globalCompositeOperation = 'screen';
        const grad = ctx.createLinearGradient(0, h, 0, horizonY);
        grad.addColorStop(0, color); grad.addColorStop(1, 'transparent');
        ctx.globalAlpha = 0.2 + Math.sin(t * 2) * 0.05;
        ctx.fillStyle = grad; ctx.fillRect(0, horizonY, w, h - horizonY);
        ctx.globalAlpha = 0.05; ctx.fillStyle = '#fff';
        for(let i=0; i<5; i++) {
            const y = h - ((t * 50 + i * 100) % (h * 0.4));
            ctx.fillRect(0, y, w, 10);
        }
    }

    private drawFogLayers(ctx: CanvasRenderingContext2D, w: number, h: number, color: string, mapConfig: MapConfig, t: number) {
        const horizonY = h * VisualMath.HORIZON_Y_PCT;
        ctx.globalCompositeOperation = 'screen';
        const fogSprite = AssetManager.getFogCloud(color);
        for (let i = 0; i < 4; i++) {
            const speed = 25, x = ((t * speed + i * (w / 4)) % (w + 400)) - 200, y = horizonY + Math.sin(i + t * 0.2) * 50;
            ctx.globalAlpha = 0.08; ctx.drawImage(fogSprite, x - 200, y - 100, 400, 200);
        }
    }

    private drawSandStorm(ctx: CanvasRenderingContext2D, w: number, h: number, t: number, color: string) {
        ctx.globalCompositeOperation = 'overlay'; 
        const windSpeed = 300, drift = t * windSpeed;
        const grad = ctx.createLinearGradient(0, 0, w, 0);
        grad.addColorStop(0, 'rgba(0,0,0,0)'); grad.addColorStop(0.5, color); grad.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.fillStyle = grad; ctx.globalAlpha = 0.2; ctx.fillRect(0, 0, w, h);
        const fogSprite = AssetManager.getFogCloud(color);
        for (let i = 0; i < 6; i++) {
            const x = ((drift + i * (w / 6)) % (w + 600)) - 300, y = (Math.sin(i * 132 + t) * 0.5 + 0.5) * h;
            ctx.globalAlpha = 0.12; ctx.drawImage(fogSprite, x, y, 500, 150);
        }
        const mistH = 200, mistY = h - mistH;
        const mistGrad = ctx.createLinearGradient(0, mistY, 0, h);
        mistGrad.addColorStop(0, 'rgba(0,0,0,0)'); mistGrad.addColorStop(0.4, color); mistGrad.addColorStop(1, 'rgba(0,0,0,0.8)');
        ctx.fillStyle = mistGrad; ctx.globalAlpha = 0.4 + Math.sin(t*3) * 0.1; ctx.fillRect(0, mistY, w, mistH);
        ctx.strokeStyle = '#fff'; ctx.globalAlpha = 0.08; ctx.lineWidth = 1; ctx.beginPath();
        for (let i = 0; i < 30; i++) {
            const streakX = ((drift * 2.5 + i * 153) % (w + 200)) - 100, streakY = (Math.sin(i * 21) * 0.5 + 0.5) * (h * 0.8) + h * 0.2;
            ctx.moveTo(streakX, streakY); ctx.lineTo(streakX + 150, streakY + 5);
        }
        ctx.stroke();
    }
}

import { GameEngine, Agent } from "../../game";
import { HexUtils } from "../../utils";
import { Hex } from "../../../types";
import { BLOCK_HEIGHT, HEX_SIZE } from "../../../constants";
import { GridCache } from "./GridCache";
import { VisualMath } from "../../math/VisualMath";

export class GridSpatial {
    public static getValidHexesInRange(centerQ: number, centerR: number, radius: number, engine: GameEngine): Hex[] {
        const candidates = HexUtils.range({q: centerQ, r: centerR}, radius);
        return candidates.filter(hex => engine.map.isValid(hex.q, hex.r));
    }

    public static getHexAtWorldPoint(wx: number, wy: number, engine: GameEngine, cache: GridCache): Hex | null {
        cache.ensure(engine);
        // 解算高度步進，匹配視覺投影
        const maxHeight = 300; 
        const step = BLOCK_HEIGHT;
        let bestHex: Hex | null = null;
        let bestH = -999;

        for (let h = 0; h <= maxHeight; h += step) {
            // 修正：解算 Y 軸時應考慮 Z 的物理貢獻
            // 視覺投影 vy = y - z -> y = vy + z
            const testY = wy + h; 
            const rounded = HexUtils.fromPx(wx, testY, engine.mapConfig);
            const tile = cache.tileMap.get(HexUtils.key(rounded));

            if (tile) {
                const visualTopY = VisualMath.getIsoVisualY(tile.py, tile.h);
                const dx = Math.abs(wx - tile.px);
                const dy = Math.abs(wy - visualTopY);

                if (dx < HEX_SIZE * 0.9 && dy < HEX_SIZE * 0.6) {
                    if (tile.h >= bestH) {
                        bestHex = rounded;
                        bestH = tile.h;
                    }
                }
            }
        }
        return bestHex;
    }

    public static getOccludedAgents(engine: GameEngine): Agent[] {
        const occluded: Agent[] = [];
        for (const a of engine.agents) {
            if (a.hp <= 0 && a.fullyDead) continue;
            const uTerrainH = engine.map.getTerrainHeight(a.q, a.r);
            const neighbors = HexUtils.neighbors({q: a.q, r: a.r});
            const currentSort = a.q + a.r;
            for (const n of neighbors) {
                // Topological occlusion check
                if ((n.q + n.r) > currentSort) {
                    if (engine.mapKeys.has(HexUtils.key(n))) {
                        if (engine.map.getTerrainHeight(n.q, n.r) > uTerrainH + 20) {
                            occluded.push(a);
                            break;
                        }
                    }
                }
            }
        }
        return occluded;
    }
}

import { RenderOp, RenderOpType } from "./RenderList";
import { TerrainRenderer } from "./grid/TerrainRenderer";
import { GridOverlays } from "./grid/GridOverlays";
import { HazardPainter } from "./grid/painters/HazardPainter";
import { SpriteManager } from "../sprites";
import { ParticleRenderer } from "../systems/vfx/renderers/ParticleRenderer";
import { ProjectileDrawer } from "./ProjectileDrawer";
import { AssetManager } from "../assets";
import { ENV_ANCHOR_X, ENV_ANCHOR_Y } from "../graphics/EnvironmentFactory";
import { HexLayout } from "../../types";
import { UnitRenderSystem } from "../systems/unit";

export class RenderDispatcher {
    public static dispatch(
        ctx: CanvasRenderingContext2D, 
        op: RenderOp, 
        layout: HexLayout, 
        globalTime: number,
        unitRenderer: UnitRenderSystem
    ) {
        const snapX = Math.round(op.tx);
        const snapY = Math.round(op.ty);

        switch (op.type) {
            case RenderOpType.TERRAIN:
                TerrainRenderer.drawBlock(ctx, snapX, snapY, op.tsize, op.th, op.ttheme, op.ttype, globalTime, layout);
                TerrainRenderer.drawTerrainDetail(ctx, snapX, snapY, op.th, op.ttype, op.tdetail, op.tq, op.tr, globalTime, layout, op.ttheme);
                // SSOT: Height-based projection inside
                GridOverlays.drawOverlays(ctx, snapX, snapY, op.th, op.tsize, op.oStatus, op.oDanger, op.oLightCol, op.oLightInt, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit, op.tq, op.tr, op.time, layout);
                break;

            case RenderOpType.HAZARD: 
                if (op.oHazard) HazardPainter.draw(ctx, snapX, snapY, op.oHazard, op.time);
                break;

            case RenderOpType.OBSTACLE:
                ctx.drawImage(SpriteManager.getObstacleSprite(op.ttype, layout), snapX - ENV_ANCHOR_X, snapY - ENV_ANCHOR_Y);
                break;

            case RenderOpType.UNIT:
                if (op.agent) unitRenderer.drawAssembly(ctx, op.agent, snapX, snapY, op.time, op.uSelected, op.uSilhouette, layout);
                break;

            case RenderOpType.DECAL:
                ctx.save();
                ctx.translate(snapX, snapY);
                ctx.scale(op.dScale, op.dScale);
                ctx.globalAlpha = Math.min(1, op.dLife);
                ctx.drawImage(AssetManager.getBlastZone(op.dColor), -64, -32, 128, 64);
                ctx.restore();
                break;

            case RenderOpType.VFX:
                if (op.particle) {
                    ctx.save();
                    ctx.translate(snapX, snapY);
                    ParticleRenderer.drawSingleParticle(ctx, op.particle, 0, 0, op.vProgress, op.vChaos, layout);
                    ctx.restore();
                }
                break;

            case RenderOpType.PROJECTILE:
                ProjectileDrawer.draw(ctx, op, globalTime);
                break;
        }
    }
}

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "../game";
import { Camera, GameRenderer } from "../renderer"; 
import { Hex, Skill } from "../../types";
import { BackgroundRenderer } from "./background";
import { TacticalRenderer } from "./tactical";
import { HUDRenderer } from "./HUDRenderer";
import { PostProcessor } from "./PostProcessor"; 
import { RenderList, RenderOpType } from "./RenderList";
import { RenderDispatcher } from "./RenderDispatcher";

export class RenderPipeline {
    private renderer: GameRenderer;
    private backgroundRenderer = new BackgroundRenderer();
    private tacticalRenderer = new TacticalRenderer();
    private hudRenderer = new HUDRenderer();
    private postProcessor = new PostProcessor();
    private renderList = new RenderList();
    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor(renderer: GameRenderer) { 
        this.renderer = renderer; 
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    public update(dt: number, engine: GameEngine) { 
        this.tacticalRenderer.update(dt, engine); 
    }

    public draw(ctx: CanvasRenderingContext2D, engine: GameEngine, camera: Camera, highlight: Agent | null, fps: number, hoveredHex: Hex | null, hoveredSkill: Skill | null, globalTime: number): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;
        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;
        const scene = engine.currentScene;
        const layout = engine.mapConfig.layout;

        ctx.resetTransform(); 
        ctx.fillStyle = '#020617'; 
        ctx.fillRect(0, 0, physicalWidth, physicalHeight);
        ctx.scale(dpr, dpr);

        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, globalTime);

        ctx.save();
        this.renderer.camera.sync(camera); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        this.renderList.reset();
        const terrainH = (q: number, r: number) => this.renderer.grid.getTerrainHeight(q, r, engine);

        this.renderer.grid.submitRenderables(this.renderList, engine, hoveredHex, hoveredSkill, highlight, engine.projectiles, this.transitionT, this.transitionPhase, globalTime);
        this.renderer.vfxRenderer.submitRenderables(this.renderList, engine, this.renderer.vfx, terrainH, engine.mapConfig, this.transitionT, this.transitionPhase, { width: logicalWidth, height: logicalHeight, camera });
        this.renderer.unit.submitRenderables(this.renderList, engine.agents, terrainH, globalTime, highlight, engine.mapConfig);

        this.renderList.sort();

        for (let i = 0; i < this.renderList.count; i++) {
            RenderDispatcher.dispatch(ctx, this.renderList.ops[i], layout, globalTime, this.renderer.unit);
        }

        const occludedAgents = this.renderer.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.renderer.unit.drawSilhouette(ctx, agent, terrainH, globalTime, engine.mapConfig);
            });
            ctx.restore();
        }

        this.renderer.statusOrchestrator.draw(ctx, engine.agents, globalTime, terrainH);
        ctx.restore(); 

        let transitionAberration = 0;
        if (this.transitionPhase !== 'IDLE') transitionAberration = 4 * this.transitionT * (1 - this.transitionT) * 0.5;
        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.renderer.camera.getTrauma(), transitionAberration);

        ctx.save(); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.renderer.grid, globalTime);
        this.hudRenderer.draw(ctx, this.renderer.hud, engine.agents, terrainH, engine.mapConfig, highlight, globalTime);
        ctx.restore(); 

        if (engine.directorTargetId) this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, globalTime);
        this.tacticalRenderer.drawDebug(ctx, fps);

        let blurAmount = engine.victory.isFinishing ? 1.0 - (engine.victory.victoryTimer / VICTORY_PHASE_DURATION) : (engine.victory.winningTeam !== null ? 1.0 : 0);
        if (this.transitionPhase === 'OUT') blurAmount = 1.0; 
        else if (this.transitionPhase === 'IN') blurAmount = 1.0 - this.transitionT;
        if (blurAmount > 0) this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, Math.max(0, Math.min(1, blurAmount)));
    }
}

import { ZoneRenderer } from "./ZoneRenderer";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { GroundHazard, HexLayout } from "../../../types";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";
import { ActiveZone } from "../../systems/ZoneSystem";
import { HexUtils } from "../../utils";
import { VisualMath } from "../../math/VisualMath";

export const GridOverlays = {
    drawOverlays(
        ctx: CanvasRenderingContext2D,
        x: number, baseY: number, 
        height: number,
        size: number,
        specialStatus: string | undefined, 
        zoneInfo: ActiveZone | undefined,    
        lightColor: string | null,
        lightIntensity: number,
        isRange: boolean,
        rangeColor: string,
        isHover: boolean,
        hasUnit: boolean,
        q: number, r: number,
        globalTime: number,
        layout: HexLayout
    ) {
        // SSOT: Calculate surface Y via projection formula
        const visualSurfaceY = VisualMath.getIsoVisualY(baseY, height);
        const drawY = VisualMath.applyLayerBias(visualSurfaceY, 'OVERLAY');

        if (specialStatus && specialStatus !== 'NONE') {
            const def = STATUS_VISUALS[specialStatus];
            if (def && def.floorColor) {
                ctx.save();
                ctx.translate(x, drawY);
                ctx.fillStyle = def.floorColor;
                ctx.globalAlpha = def.floorOpacity || 0.4;
                HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
                ctx.fill();
                ctx.restore();
            }
        }

        if (zoneInfo) {
            const dist = HexUtils.dist({q, r}, {q: zoneInfo.q, r: zoneInfo.r});
            ZoneRenderer.drawTileZoneEffect(
                ctx, x, drawY - 1, size,
                dist,
                zoneInfo.radius,
                zoneInfo.color,
                zoneInfo.progress,
                zoneInfo.isEnemy,
                layout
            );
        }

        if (lightColor && lightIntensity > 0) {
            ctx.save();
            ctx.translate(x, drawY);
            ctx.globalCompositeOperation = 'screen'; 
            ctx.fillStyle = lightColor;
            ctx.globalAlpha = Math.min(0.5, lightIntensity * 0.4);
            HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
            ctx.fill();
            ctx.restore();
        }

        if (isRange || isHover || hasUnit) {
            ctx.save();
            ctx.translate(x, drawY + 1); 
            ctx.globalCompositeOperation = 'screen';
            if (isRange) { 
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.12;
                HexGeometry.traceHex(ctx, 0, 0, size * 0.95, true, layout);
                ctx.fill();
                ctx.strokeStyle = rangeColor;
                ctx.lineWidth = 1.5;
                ctx.globalAlpha = 0.3;
                HexGeometry.traceHex(ctx, 0, 0, size * 0.9, true, layout);
                ctx.stroke();
            }
            if (isHover) { 
                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 2;
                ctx.globalAlpha = 0.8;
                HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
                ctx.stroke();
            }
            ctx.restore();
        }
    }
};

import { Agent, GameEngine } from "../game";
import { GridSystem } from "../systems/grid";
import { HexUtils } from "../utils";
import { UNIT_BODY_OFFSET, UNIT_HOVER_OFFSET, UNIT_VISUAL_HEIGHT, UNIT_SCALE } from "../../constants";

export interface Point3D {
    x: number;
    y: number;
    z: number;
}

export class VisualMath {
    public static readonly HORIZON_Y_PCT = 0.62;
    public static readonly PROJECTILE_HIT_TOLERANCE_SQ = 900; // 30px radius in 3D space

    public static readonly Z_LAYERS = {
        TERRAIN: 0,
        HAZARD: 3,
        OVERLAY: 5,
        SHADOW: 8,
        UNIT_FEET: 0
    };

    /**
     * SSOT: 唯一 3D 距離計算法
     */
    public static dist3DSq(a: Point3D, b: Point3D): number {
        return (a.x - b.x) ** 2 + (a.y - b.y) ** 2 + (a.z - b.z) ** 2;
    }

    public static getIsoVisualY(y: number, z: number, extraOffset: number = 0): number {
        return y - z + extraOffset;
    }

    public static applyLayerBias(visualY: number, layer: keyof typeof VisualMath.Z_LAYERS): number {
        return visualY - this.Z_LAYERS[layer];
    }

    public static getVisualBodyCenterY(surfaceY: number, z: number): number {
        return surfaceY - z - UNIT_BODY_OFFSET - UNIT_HOVER_OFFSET;
    }

    public static getUnitAnchor(agent: Agent, engine: GameEngine, grid: GridSystem | null = null): Point3D {
        const terrainH = grid 
            ? grid.getTerrainHeight(agent.q, agent.r, engine) 
            : engine.map.getTerrainHeight(agent.q, agent.r);
        const chestHeight = (UNIT_VISUAL_HEIGHT * 0.45) * UNIT_SCALE;
        const z = terrainH + agent.physics.z + UNIT_BODY_OFFSET + UNIT_HOVER_OFFSET + chestHeight;
        return { x: agent.px, y: agent.py, z: z };
    }

    public static resolveTargetPoint(targetId: string, engine: GameEngine): Point3D {
        if (!targetId) return { x: 0, y: 0, z: -9999 };
        const agent = engine.agents.find(a => a.id === agentId);
        if (agent) return this.getUnitAnchor(agent, engine);
        if (targetId.startsWith("ground-")) {
            const parts = targetId.split("-")[1].split(",");
            if (parts.length === 2) {
                const q = parseInt(parts[0]);
                const r = parseInt(parts[1]);
                const p = HexUtils.toPx(q, r, engine.mapConfig);
                const h = engine.map.getTerrainHeight(q, r);
                return { x: p.x, y: p.y, z: h + 2 };
            }
        }
        return { x: 0, y: 0, z: -9999 };
    }
}

import { Agent, GameEngine } from "../../game";
import { Projectile, Skill, Team } from "../../../types";
import { HexUtils } from "../../utils";
import { SkillExecutor } from "./SkillExecutor";
import { VisualMath, Point3D } from "../../math/VisualMath";
import { HazardManager } from "./HazardManager";

export class ProjectileSystem {
    private pool: Projectile[] = [];

    constructor() {
        for (let i = 0; i < 60; i++) this.pool.push(this.createEmptyProjectile());
    }

    public update(dt: number, engine: GameEngine, skillExecutor: SkillExecutor) {
        const list = engine.projectiles;
        for (let i = list.length - 1; i >= 0; i--) {
            const p = list[i];
            if (!p.active) { this.removeProjectile(i, engine); continue; }

            // SSOT: 獲取目標目前的 3D 真實座標
            const targetPoint = VisualMath.resolveTargetPoint(p.targetId, engine);
            if (targetPoint.z > -9000) p.targetPos = { x: targetPoint.x, y: targetPoint.y };

            // 邏輯位移步進 (維持物理座標模擬)
            const dx = p.targetPos.x - p.x;
            const dy = p.targetPos.y - p.y;
            const distSq2D = dx*dx + dy*dy;
            const moveStep = Math.max(300, p.speed) * dt;

            // SSOT: 命中判定改為基於 3D 邏輯座標 (模擬物體在 3D 空間接近)
            // 我們假設飛行物高度 z 會隨著進度解算，但在邏輯層我們使用 3D 距離閾值
            const current3D: Point3D = { x: p.x, y: p.y, z: p.startZ || 0 }; // 這裡簡化了 Z 軸動畫的邏輯影響，主要以 XY 接近度判定
            const target3D: Point3D = targetPoint;

            // 判定：像素移動步長或固定容差
            if (distSq2D < (moveStep * moveStep * 2) || distSq2D < VisualMath.PROJECTILE_HIT_TOLERANCE_SQ) {
                this.handleImpact(p, engine, skillExecutor);
                this.release(p);
                this.removeProjectile(i, engine);
            } else {
                const mag = Math.sqrt(distSq2D);
                p.x += (dx / mag) * moveStep;
                p.y += (dy / mag) * moveStep;
            }
        }
    }

    private handleImpact(p: Projectile, engine: GameEngine, skillExecutor: SkillExecutor) {
        const source = engine.agents.find(a => a.id === p.sourceId);
        const hitPos = p.targetPos;

        if (p.skill.type === 'AOE') {
            const radius = p.skill.aoeRadius || 1;
            const hitHex = HexUtils.fromPx(hitPos.x, hitPos.y, engine.mapConfig);
            engine.agents.forEach(t => {
                if (t.team !== p.team && t.hp > 0 && !t.banished) {
                    if (HexUtils.dist(hitHex, t) <= radius) {
                        if (source) skillExecutor.resolveHit(source, t, p.skill, hitPos, engine);
                    }
                }
            });
            if (source) HazardManager.spawnHazards(source, HexUtils.range(hitHex, radius), p.skill, engine);
            engine.events.push({ type: 'IMPACT_AOE', pos: hitPos, skill: p.skill, color: p.skill.color });
        } else {
            const target = engine.agents.find(a => a.id === p.targetId);
            if (target && target.hp > 0 && !target.banished) {
                if (source) skillExecutor.resolveHit(source, target, p.skill, undefined, engine);
            }
        }
        engine.events.push({ type: 'PROJECTILE_HIT', pos: hitPos, skill: p.skill });
    }

    private removeProjectile(idx: number, engine: GameEngine) {
        const last = engine.projectiles.pop();
        if (last && idx < engine.projectiles.length) engine.projectiles[idx] = last;
    }

    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        const target = skill.type === 'AOE' ? (source.targetHex || source.target) : source.target;
        if (!target) return;
        const targetId = (target as any).id || `ground-${(target as any).q},${(target as any).r}`;
        const targetPos = (target as any).px !== undefined ? {x:(target as any).px, y:(target as any).py} : HexUtils.toPx((target as any).q, (target as any).r, engine.mapConfig);
        const launchAnchor = VisualMath.getUnitAnchor(source, engine);
        const p = this.pool.pop() || this.createEmptyProjectile();
        p.active = true; p.createdAt = engine.battleTime; p.lifespan = 5.0; p.id = Math.random().toString(36).substr(2, 6);
        p.x = source.px; p.y = source.py; p.startX = source.px; p.startY = source.py; p.startZ = launchAnchor.z;
        p.targetId = targetId; p.targetPos = targetPos; p.speed = skill.projectileSpeed || 800;
        p.skill = skill; p.sourceId = source.id; p.team = source.team; p.trail = [];
        engine.projectiles.push(p);
        engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill: skill, targetId: targetId });
    }

    private release(p: Projectile) { p.active = false; p.trail = []; this.pool.push(p); }
    private createEmptyProjectile(): Projectile {
        return { id: '', active: false, createdAt: 0, lifespan: 0, x: 0, y: 0, startX: 0, startY: 0, startZ: 0, targetId: '', targetPos: {x: 0, y: 0}, speed: 0, skill: {} as Skill, sourceId: '', team: Team.BLUE, trail: [] };
    }
}

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "../game";
import { Camera, GameRenderer } from "../renderer"; 
import { Hex, Skill } from "../../types";
import { BackgroundRenderer } from "./background";
import { TacticalRenderer } from "./tactical";
import { HUDRenderer } from "./HUDRenderer";
import { PostProcessor } from "./PostProcessor"; 
import { RenderList } from "./RenderList";
import { RenderDispatcher } from "./RenderDispatcher";

export class RenderPipeline {
    private renderer: GameRenderer;
    private background = new BackgroundRenderer();
    private tactical = new TacticalRenderer();
    private hud = new HUDRenderer();
    private post = new PostProcessor();
    private renderList = new RenderList();
    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor(renderer: GameRenderer) { 
        this.renderer = renderer; 
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    public update(dt: number, engine: GameEngine) { 
        this.tactical.update(dt, engine); 
    }

    public draw(ctx: CanvasRenderingContext2D, engine: GameEngine, camera: Camera, highlight: Agent | null, fps: number, hoveredHex: Hex | null, hoveredSkill: Skill | null, globalTime: number): void {
        const { width: pW, height: pH } = ctx.canvas;
        if (pW === 0 || pH === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const [lW, lH] = [pW / dpr, pH / dpr];
        const { mapConfig: cfg, currentScene: sc } = engine;

        // 1. Clear & Background
        ctx.resetTransform(); 
        ctx.fillStyle = '#020617'; 
        ctx.fillRect(0, 0, pW, pH);
        ctx.scale(dpr, dpr);
        this.background.draw(ctx, lW, lH, sc, cfg, globalTime);

        // 2. Main Scene (World Space)
        ctx.save();
        this.renderer.camera.sync(camera); 
        this.renderer.camera.applyTransform(ctx, lW, lH);
        this.drawWorld(ctx, engine, camera, highlight, hoveredHex, hoveredSkill, globalTime);
        ctx.restore(); 

        // 3. Post Processing
        let transAb = (this.transitionPhase !== 'IDLE') ? 4 * this.transitionT * (1 - this.transitionT) * 0.5 : 0;
        this.post.apply(ctx, pW, pH, this.renderer.camera.getTrauma(), transAb);

        // 4. Overlays (Screen/World Hybrid)
        ctx.save(); 
        this.renderer.camera.applyTransform(ctx, lW, lH);
        this.tactical.drawOverlay(ctx, engine, highlight, this.renderer.grid, globalTime);
        this.hud.draw(ctx, this.renderer.hud, engine.agents, (q, r) => this.renderer.grid.getTerrainHeight(q, r, engine), cfg, highlight, globalTime);
        ctx.restore(); 

        if (engine.directorTargetId) this.tactical.drawHUD(ctx, engine, lW, lH, camera, globalTime);
        this.tactical.drawDebug(ctx, fps);

        // 5. Global Transition/Finish Blur
        let blur = engine.victory.isFinishing ? 1.0 - (engine.victory.victoryTimer / VICTORY_PHASE_DURATION) : (engine.victory.winningTeam !== null ? 1.0 : 0);
        if (this.transitionPhase === 'OUT') blur = 1.0; 
        else if (this.transitionPhase === 'IN') blur = 1.0 - this.transitionT;
        if (blur > 0) this.post.applyFinishBlur(ctx, pW, pH, Math.max(0, Math.min(1, blur)));
    }

    private drawWorld(ctx: CanvasRenderingContext2D, engine: GameEngine, camera: Camera, highlight: Agent | null, hoveredHex: Hex | null, hoveredSkill: Skill | null, t: number) {
        this.renderList.reset();
        const terrainH = (q: number, r: number) => this.renderer.grid.getTerrainHeight(q, r, engine);
        const lW = ctx.canvas.width / (window.devicePixelRatio || 1);
        const lH = ctx.canvas.height / (window.devicePixelRatio || 1);

        this.renderer.grid.submitRenderables(this.renderList, engine, hoveredHex, hoveredSkill, highlight, engine.projectiles, this.transitionT, this.transitionPhase, t);
        this.renderer.vfxRenderer.submitRenderables(this.renderList, engine, this.renderer.vfx, terrainH, engine.mapConfig, this.transitionT, this.transitionPhase, { width: lW, height: lH, camera });
        this.renderer.unit.submitRenderables(this.renderList, engine.agents, terrainH, t, highlight, engine.mapConfig);

        this.renderList.sort();
        for (let i = 0; i < this.renderList.count; i++) {
            RenderDispatcher.dispatch(ctx, this.renderList.ops[i], engine.mapConfig.layout, t, this.renderer.unit);
        }

        const occluded = this.renderer.grid.getOccludedAgents(engine);
        if (occluded.length > 0) {
            ctx.save();
            occluded.forEach(a => this.renderer.unit.drawSilhouette(ctx, a, terrainH, t, engine.mapConfig));
            ctx.restore();
        }
        this.renderer.statusOrchestrator.draw(ctx, engine.agents, t, terrainH);
    }
}

import { useRef, useState, useCallback, useEffect } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Team, Skill, Role, HexLayout } from '../types';
import { SCENE_DB } from '../data/scenes';
import { DesignExporter } from '../engine/systems/DesignExporter';
import { DEFAULT_HEX_LAYOUT } from '../constants';

export const useGameApp = () => {
    const engineRef = useRef(new GameEngine());

    // 1. Session & Gameplay State
    const [isPlaying, setIsPlaying] = useState(false);
    const [winner, setWinner] = useState<Team | null>(null);
    const [timeScale, setTimeScale] = useState(1.0);
    const [isShowcaseMode, setIsShowcaseMode] = useState(true);
    const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');

    // 2. Editor & Configuration State
    const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
    const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL'); 
    const [hpInput, setHpInput] = useState(600); 
    const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
    const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);
    const [hexLayout, setHexLayout] = useState<HexLayout>(DEFAULT_HEX_LAYOUT);
    const [mapW, setMapW] = useState(12);
    const [mapH, setMapH] = useState(8);
    const [currentSceneId, setCurrentSceneId] = useState('VOID');

    // 3. UI & Inspector State
    const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
    const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);
    const [showLogs, setShowLogs] = useState(false);
    const [showDB, setShowDB] = useState(false);
    const [showVFXMap, setShowVFXMap] = useState(false); 
    const [showFactionWarning, setShowFactionWarning] = useState(false);
    const [unitCount, setUnitCount] = useState(0); 

    useEffect(() => {
        const engine = engineRef.current;
        const handleGameOver = (data: { winner: Team }) => {
            setWinner(data.winner);
            if (engine.isRunning) engine.stop(); 
            setIsPlaying(false);
        };
        engine.bus.on('GAME_OVER', handleGameOver);
        return () => engine.bus.off('GAME_OVER', handleGameOver);
    }, []);

    useEffect(() => {
        if (isShowcaseMode && winner !== null) {
            const timer = setTimeout(() => {
                setTransitionPhase('OUT');
                engineRef.current.agents = [];
                engineRef.current.projectiles = [];
                setTimeout(() => {
                    setupShowcaseMap(); 
                    setTransitionPhase('IN'); 
                    setTimeout(() => {
                        setTransitionPhase('IDLE');
                        spawnShowcaseUnits(); 
                    }, 1800);
                }, 1800);
            }, 1000); 
            return () => clearTimeout(timer);
        }
    }, [winner, isShowcaseMode]);

    const setupShowcaseMap = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);
        engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
        engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
        const newLayout: HexLayout = Math.random() > 0.5 ? 'FLAT' : 'POINTY';
        engine.mapConfig.layout = newLayout;
        setHexLayout(newLayout);
        engine.randomizeEnvironment(); 
        setCurrentSceneId(engine.currentScene.id);
    }, []);

    const spawnShowcaseUnits = useCallback(() => {
        const engine = engineRef.current;
        let validHexes = (Array.from(engine.mapKeys) as string[])
            .map(k => { const [q, r] = k.split(',').map(Number); return {q, r}; })
            .filter(h => !engine.map.hasObstacle(h.q, h.r));
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }
        let spawnIndex = 0;
        const TARGET_PER_TEAM = 5;
        const roles: Role[] = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];
        const spawnTeam = (team: Team) => {
            let count = 0;
            while (count < TARGET_PER_TEAM && spawnIndex < validHexes.length) {
                const h = validHexes[spawnIndex++];
                const hp = 500 + Math.floor(Math.random() * 400); 
                const role = roles[count % roles.length];
                const agent = engine.addAgent(team, h.q, h.r, hp, role);
                if (agent) count++;
            }
        };
        spawnTeam(Team.BLUE);
        spawnTeam(Team.RED);
        engine.play();
        setIsPlaying(true);
    }, []);

    const startShowcaseMatch = useCallback(() => {
        setupShowcaseMap();
        spawnShowcaseUnits();
    }, [setupShowcaseMap, spawnShowcaseUnits]);

    useEffect(() => { startShowcaseMatch(); }, [startShowcaseMatch]);
    useEffect(() => {
        const interval = setInterval(() => setUnitCount(engineRef.current.agents.length), 500); 
        return () => clearInterval(interval);
    }, []);
    useEffect(() => { engineRef.current.timeScale = timeScale; }, [timeScale]);

    const enterManualMode = () => {
        setIsShowcaseMode(false);
        engineRef.current.stop();
        setIsPlaying(false);
        setWinner(null);
        engineRef.current.clear(true); 
        engineRef.current.agents = [];
        setUnitCount(0);
        setMapW(engineRef.current.mapConfig.w);
        setMapH(engineRef.current.mapConfig.h);
        setHexLayout(engineRef.current.mapConfig.layout);
        setCurrentSceneId(engineRef.current.currentScene.id);
    };

    const handleUpdateMapSize = useCallback((w: number, h: number) => {
        setMapW(w); setMapH(h);
        engineRef.current.mapConfig.w = w;
        engineRef.current.mapConfig.h = h;
        engineRef.current.clear(false); 
        setSelectedAgent(null); setWinner(null);
    }, []);

    const handleUpdateLayout = useCallback((l: HexLayout) => {
        setHexLayout(l);
        engineRef.current.mapConfig.layout = l;
        engineRef.current.clear(true); 
        setSelectedAgent(null); setWinner(null);
    }, []);

    const handleSetScene = useCallback((id: string) => {
        const scene = SCENE_DB.find(s => s.id === id);
        if (scene) {
            engineRef.current.currentScene = scene;
            engineRef.current.map.rebuildMap(engineRef.current);
            setCurrentSceneId(id);
        }
    }, []);

    const handleRandomBattlefield = useCallback(() => {
        const engine = engineRef.current;
        engine.stop(); setWinner(null); setSelectedAgent(null); engine.clear(false); 
        const newLayout: HexLayout = Math.random() > 0.5 ? 'FLAT' : 'POINTY';
        engine.mapConfig.layout = newLayout;
        setHexLayout(newLayout);
        engine.randomizeEnvironment();
        setMapW(engine.mapConfig.w); setMapH(engine.mapConfig.h);
        setCurrentSceneId(engine.currentScene.id);
        let validHexes = (Array.from(engine.mapKeys) as string[])
            .map(k => { const [q, r] = k.split(',').map(Number); return {q, r}; })
            .filter(h => !engine.map.hasObstacle(h.q, h.r));
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }
        let spawnIndex = 0;
        const TARGET_PER_TEAM = 5;
        const roles: Role[] = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];
        const spawnTeam = (team: Team) => {
            let count = 0;
            while (count < TARGET_PER_TEAM && spawnIndex < validHexes.length) {
                const h = validHexes[spawnIndex++];
                const hp = 500 + Math.floor(Math.random() * 400); 
                const role = roles[count % roles.length];
                const agent = engine.addAgent(team, h.q, h.r, hp, role);
                if (agent) count++;
            }
        };
        spawnTeam(Team.BLUE); spawnTeam(Team.RED);
        setIsPlaying(false); 
    }, []);

    const handleNextLevel = useCallback(() => {
        handleRandomBattlefield();
        const engine = engineRef.current;
        engine.play(); setIsPlaying(true); setTool(ToolType.SELECT);
    }, [handleRandomBattlefield]);

    const handleReset = useCallback(() => {
        engineRef.current.restart(); setIsPlaying(false); setWinner(null);
    }, []);

    const togglePlay = useCallback(() => {
        if (winner !== null) return;
        if (isPlaying) {
            engineRef.current.stop(); setIsPlaying(false);
        } else {
            const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
            const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);
            if (!hasBlue || !hasRed) {
                setShowFactionWarning(true);
                setTimeout(() => setShowFactionWarning(false), 2500);
                return;
            }
            engineRef.current.play(); setIsPlaying(true); setTool(ToolType.SELECT);
        }
    }, [isPlaying, winner]);

    return {
        engineRef,
        state: { isShowcaseMode, isPlaying, unitCount, tool, selectedObstacle, selectedAgent, hoveredSkill, hpInput, mapW, mapH, timeScale, winner, currentSceneId, spawnMode, draftRole, showLogs, showDB, showVFXMap, transitionPhase, showFactionWarning, hexLayout },
        setters: { setTool, setSelectedObstacle, setHpInput, setTimeScale, setSpawnMode, setDraftRole, setShowLogs, setShowDB, setShowVFXMap, setIsShowcaseMode, setSelectedAgent, setHoveredSkill },
        actions: { enterManualMode, handleUpdateMapSize, handleUpdateLayout, handleSetScene, handleRandomBattlefield, handleNextLevel, handleReset, togglePlay, onWin: (team: Team) => { engineRef.current.bus.emit('GAME_OVER', {winner: team}) }, handleSelectAgent: setSelectedAgent, startShowcaseMatch, downloadSpec: DesignExporter.downloadSpec, rematch: () => { setWinner(null); engineRef.current.restart(); engineRef.current.play(); setIsPlaying(true); } }
    };
};

import { Agent, GameEngine } from "../game";
import { GridSystem } from "../systems/grid";
import { HexUtils } from "../utils";
import { UNIT_BODY_OFFSET, UNIT_HOVER_OFFSET, UNIT_VISUAL_HEIGHT, UNIT_SCALE } from "../../constants";

export interface Point3D {
    x: number;
    y: number;
    z: number;
}

export class VisualMath {
    public static readonly HORIZON_Y_PCT = 0.62;
    public static readonly PROJECTILE_HIT_TOLERANCE_SQ = 900; // 30px radius in 3D space

    public static readonly Z_LAYERS = {
        TERRAIN: 0,
        HAZARD: 3,
        OVERLAY: 5,
        SHADOW: 8,
        UNIT_FEET: 0
    };

    /**
     * SSOT: 唯一 3D 距離計算法
     */
    public static dist3DSq(a: Point3D, b: Point3D): number {
        return (a.x - b.x) ** 2 + (a.y - b.y) ** 2 + (a.z - b.z) ** 2;
    }

    public static getIsoVisualY(y: number, z: number, extraOffset: number = 0): number {
        return y - z + extraOffset;
    }

    public static applyLayerBias(visualY: number, layer: keyof typeof VisualMath.Z_LAYERS): number {
        return visualY - this.Z_LAYERS[layer];
    }

    public static getVisualBodyCenterY(surfaceY: number, z: number): number {
        return surfaceY - z - UNIT_BODY_OFFSET - UNIT_HOVER_OFFSET;
    }

    public static getUnitAnchor(agent: Agent, engine: GameEngine, grid: GridSystem | null = null): Point3D {
        const terrainH = grid 
            ? grid.getTerrainHeight(agent.q, agent.r, engine) 
            : engine.map.getTerrainHeight(agent.q, agent.r);
        const chestHeight = (UNIT_VISUAL_HEIGHT * 0.45) * UNIT_SCALE;
        const z = terrainH + agent.physics.z + UNIT_BODY_OFFSET + UNIT_HOVER_OFFSET + chestHeight;
        return { x: agent.px, y: agent.py, z: z };
    }

    public static resolveTargetPoint(targetId: string, engine: GameEngine): Point3D {
        if (!targetId) return { x: 0, y: 0, z: -9999 };
        // FIX: Change agentId to targetId to resolve the reference error
        const agent = engine.agents.find(a => a.id === targetId);
        if (agent) return this.getUnitAnchor(agent, engine);
        if (targetId.startsWith("ground-")) {
            const parts = targetId.split("-")[1].split(",");
            if (parts.length === 2) {
                const q = parseInt(parts[0]);
                const r = parseInt(parts[1]);
                const p = HexUtils.toPx(q, r, engine.mapConfig);
                const h = engine.map.getTerrainHeight(q, r);
                return { x: p.x, y: p.y, z: h + 2 };
            }
        }
        return { x: 0, y: 0, z: -9999 };
    }
}

import { Agent, GameEngine } from "../game";
import { GridSystem } from "../systems/grid";
import { HexUtils } from "../utils";
import { UNIT_BODY_OFFSET, UNIT_HOVER_OFFSET, UNIT_VISUAL_HEIGHT, UNIT_SCALE } from "../../constants";

export interface Point3D {
    x: number;
    y: number;
    z: number;
}

export class VisualMath {
    public static readonly HORIZON_Y_PCT = 0.62;
    public static readonly PROJECTILE_HIT_TOLERANCE_SQ = 900; 

    public static readonly Z_LAYERS = {
        TERRAIN: 0,
        HAZARD: 3,
        OVERLAY: 5,
        SHADOW: 8,
        UNIT_FEET: 0
    };

    /**
     * SSOT: 基礎投影公式 vy = y - z
     */
    public static getIsoVisualY(y: number, z: number, extraOffset: number = 0): number {
        return y - z + extraOffset;
    }

    /**
     * SSOT: 計算包含物理偏移的單位視覺中心 Y 軸
     */
    public static getEntityVisualY(logicY: number, terrainH: number, physY: number, physZ: number, extraY: number = 0): number {
        const totalY = logicY + physY;
        const totalZ = terrainH + physZ;
        return (totalY - totalZ) + extraY;
    }

    public static applyLayerBias(visualY: number, layer: keyof typeof VisualMath.Z_LAYERS): number {
        return visualY - this.Z_LAYERS[layer];
    }

    public static getVisualBodyCenterY(surfaceY: number, z: number): number {
        return surfaceY - z - UNIT_BODY_OFFSET - UNIT_HOVER_OFFSET;
    }

    public static getUnitAnchor(agent: Agent, engine: GameEngine, grid: GridSystem | null = null): Point3D {
        const terrainH = grid 
            ? grid.getTerrainHeight(agent.q, agent.r, engine) 
            : engine.map.getTerrainHeight(agent.q, agent.r);
        const chestHeight = (UNIT_VISUAL_HEIGHT * 0.45) * UNIT_SCALE;
        const z = terrainH + agent.physics.z + UNIT_BODY_OFFSET + UNIT_HOVER_OFFSET + chestHeight;
        return { x: agent.px + agent.physics.x, y: agent.py + agent.physics.y, z: z };
    }

    public static resolveTargetPoint(targetId: string, engine: GameEngine): Point3D {
        if (!targetId) return { x: 0, y: 0, z: -9999 };
        const agent = engine.agents.find(a => a.id === targetId);
        if (agent) return this.getUnitAnchor(agent, engine);
        if (targetId.startsWith("ground-")) {
            const parts = targetId.split("-")[1].split(",");
            if (parts.length === 2) {
                const q = parseInt(parts[0]);
                const r = parseInt(parts[1]);
                const p = HexUtils.toPx(q, r, engine.mapConfig);
                const h = engine.map.getTerrainHeight(q, r);
                return { x: p.x, y: p.y, z: h + 2 };
            }
        }
        return { x: 0, y: 0, z: -9999 };
    }
}

import { Agent } from "../game";
import { HUD_BAR_OFFSET } from "../../constants";
import { HexUtils, MapConfig } from "../utils";
import { HUDSystem } from "../systems/hud";
import { VisualMath } from "../math/VisualMath";
import { BarPainter } from "./hud/BarPainter";
import { GaugePainter } from "./hud/GaugePainter";
import { TextPainter } from "./hud/TextPainter";

export class HUDRenderer {
    public draw(ctx: CanvasRenderingContext2D, hud: HUDSystem, agents: Agent[], getTerrainHeight: (q: number, r: number) => number, mapConfig: MapConfig, highlight: Agent | null, time: number) {
        agents.forEach(a => {
            if (a.hp <= 0 || a.spawnTimer > 0) return;

            let h = 0;
            if (a.isMoving && a.path.length > 0) {
                const startH = getTerrainHeight(a.q, a.r);
                const endH = getTerrainHeight(a.path[0].q, a.path[0].r);
                h = HexUtils.lerp(startH, endH, a.moveProgress);
            } else {
                const vHex = HexUtils.fromPx(a.px, a.py, mapConfig);
                h = getTerrainHeight(vHex.q, vHex.r);
            }

            // SSOT: Use Unified Projection Formula
            const anchorY = VisualMath.getEntityVisualY(a.py, h, a.physics.y, a.physics.z, -HUD_BAR_OFFSET);
            const headX = a.px + a.physics.x;

            const isSelected = (a === highlight);
            BarPainter.drawUnitBars(ctx, a, headX, anchorY, isSelected);
            GaugePainter.drawUnitStatusGauges(ctx, a, headX, anchorY);
        });
        TextPainter.drawFloatingText(ctx, hud);
    }
}

import { Agent, GameEngine } from "../../game";
import { Projectile, Skill, Team } from "../../../types";
import { HexUtils } from "../../utils";
import { SkillExecutor } from "./SkillExecutor";
import { VisualMath, Point3D } from "../../math/VisualMath";
import { HazardManager } from "./HazardManager";

export class ProjectileSystem {
    private pool: Projectile[] = [];

    constructor() {
        for (let i = 0; i < 60; i++) this.pool.push(this.createEmptyProjectile());
    }

    public update(dt: number, engine: GameEngine, skillExecutor: SkillExecutor) {
        const list = engine.projectiles;
        for (let i = list.length - 1; i >= 0; i--) {
            const p = list[i];
            if (!p.active) { this.removeProjectile(i, engine); continue; }

            const targetPoint = VisualMath.resolveTargetPoint(p.targetId, engine);
            if (targetPoint.z > -9000) {
                p.targetPos = { x: targetPoint.x, y: targetPoint.y };
            }

            const moveStep = Math.max(300, p.speed) * dt;

            // SSOT: 3D 空間距離判定
            const dx = targetPoint.x - p.x;
            const dy = targetPoint.y - p.y;
            const dz = targetPoint.z - (p.startZ || 0); // 這裡簡化 Z 為線性，實際視覺拋物線僅為呈現
            const distSq3D = dx*dx + dy*dy + dz*dz;

            if (distSq3D < (moveStep * moveStep * 2.5) || distSq3D < VisualMath.PROJECTILE_HIT_TOLERANCE_SQ) {
                this.handleImpact(p, engine, skillExecutor);
                this.release(p);
                this.removeProjectile(i, engine);
            } else {
                const dist3D = Math.sqrt(distSq3D);
                p.x += (dx / dist3D) * moveStep;
                p.y += (dy / dist3D) * moveStep;
                // z 軸邏輯由 ProjectileRenderer 根據 progress 解算，系統僅維護其 XY 世界位置
            }
        }
    }

    private handleImpact(p: Projectile, engine: GameEngine, skillExecutor: SkillExecutor) {
        const source = engine.agents.find(a => a.id === p.sourceId);
        const hitPos = p.targetPos;

        if (p.skill.type === 'AOE') {
            const radius = p.skill.aoeRadius || 1;
            const hitHex = HexUtils.fromPx(hitPos.x, hitPos.y, engine.mapConfig);
            engine.agents.forEach(t => {
                if (t.team !== p.team && t.hp > 0 && !t.banished) {
                    if (HexUtils.dist(hitHex, t) <= radius) {
                        if (source) skillExecutor.resolveHit(source, t, p.skill, hitPos, engine);
                    }
                }
            });
            if (source) HazardManager.spawnHazards(source, HexUtils.range(hitHex, radius), p.skill, engine);
            engine.events.push({ type: 'IMPACT_AOE', pos: hitPos, skill: p.skill, color: p.skill.color });
        } else {
            const target = engine.agents.find(a => a.id === p.targetId);
            if (target && target.hp > 0 && !target.banished) {
                if (source) skillExecutor.resolveHit(source, target, p.skill, undefined, engine);
            }
        }
        engine.events.push({ type: 'PROJECTILE_HIT', pos: hitPos, skill: p.skill });
    }

    private removeProjectile(idx: number, engine: GameEngine) {
        const last = engine.projectiles.pop();
        if (last && idx < engine.projectiles.length) engine.projectiles[idx] = last;
    }

    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        const target = skill.type === 'AOE' ? (source.targetHex || source.target) : source.target;
        if (!target) return;
        const targetId = (target as any).id || `ground-${(target as any).q},${(target as any).r}`;
        const targetPos = (target as any).px !== undefined ? {x:(target as any).px, y:(target as any).py} : HexUtils.toPx((target as any).q, (target as any).r, engine.mapConfig);
        const launchAnchor = VisualMath.getUnitAnchor(source, engine);

        const p = this.pool.pop() || this.createEmptyProjectile();
        p.active = true; p.createdAt = engine.battleTime; p.lifespan = 5.0; p.id = Math.random().toString(36).substr(2, 6);
        p.x = source.px; p.y = source.py; p.startX = source.px; p.startY = source.py; p.startZ = launchAnchor.z;
        p.targetId = targetId; p.targetPos = targetPos; p.speed = skill.projectileSpeed || 800;
        p.skill = skill; p.sourceId = source.id; p.team = source.team; p.trail = [];
        engine.projectiles.push(p);
        engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill: skill, targetId: targetId });
    }

    private release(p: Projectile) { p.active = false; p.trail = []; this.pool.push(p); }
    private createEmptyProjectile(): Projectile {
        return { id: '', active: false, createdAt: 0, lifespan: 0, x: 0, y: 0, startX: 0, startY: 0, startZ: 0, targetId: '', targetPos: {x: 0, y: 0}, speed: 0, skill: {} as Skill, sourceId: '', team: Team.BLUE, trail: [] };
    }
}

import { Agent, GameEngine } from "../game";
import { GridSystem } from "../systems/grid";
import { HexUtils } from "../utils";
import { UNIT_BODY_OFFSET, UNIT_HOVER_OFFSET, UNIT_VISUAL_HEIGHT, UNIT_SCALE, VISUAL_ANCHORS } from "../../constants";

export interface Point3D {
    x: number;
    y: number;
    z: number;
}

export class VisualMath {
    public static readonly HORIZON_Y_PCT = 0.62;
    public static readonly PROJECTILE_HIT_TOLERANCE_SQ = 900; 

    public static readonly Z_LAYERS = {
        TERRAIN: 0,
        HAZARD: 3,
        HAZARD_FOG: -15, // Relative to Hazard base
        OVERLAY: 5,
        SHADOW: 8,
        UNIT_FEET: 0,
        LIQUID_OFFSET: 1
    };

    public static getIsoVisualY(y: number, z: number, extraOffset: number = 0): number {
        return y - z + extraOffset;
    }

    public static getEntityVisualY(logicY: number, terrainH: number, physY: number, physZ: number, extraY: number = 0): number {
        return (logicY + physY) - (terrainH + physZ) + extraY;
    }

    public static getOverheadVisualY(surfaceY: number, z: number, bob: number = 0): number {
        const bodyCenterY = this.getVisualBodyCenterY(surfaceY, z);
        return bodyCenterY - VISUAL_ANCHORS.HEAD_OFFSET_Y - 10 + bob;
    }

    public static applyLayerBias(visualY: number, layer: keyof typeof VisualMath.Z_LAYERS): number {
        const bias = this.Z_LAYERS[layer];
        return visualY - bias;
    }

    public static getVisualBodyCenterY(surfaceY: number, z: number): number {
        return surfaceY - z - UNIT_BODY_OFFSET - UNIT_HOVER_OFFSET;
    }

    public static getUnitAnchor(agent: Agent, engine: GameEngine, grid: GridSystem | null = null): Point3D {
        const terrainH = grid 
            ? grid.getTerrainHeight(agent.q, agent.r, engine) 
            : engine.map.getTerrainHeight(agent.q, agent.r);
        const chestHeight = (UNIT_VISUAL_HEIGHT * 0.45) * UNIT_SCALE;
        const z = terrainH + agent.physics.z + UNIT_BODY_OFFSET + UNIT_HOVER_OFFSET + chestHeight;
        return { x: agent.px + agent.physics.x, y: agent.py + agent.physics.y, z: z };
    }

    public static resolveTargetPoint(targetId: string, engine: GameEngine): Point3D {
        if (!targetId) return { x: 0, y: 0, z: -9999 };
        const agent = engine.agents.find(a => a.id === targetId);
        if (agent) return this.getUnitAnchor(agent, engine);
        if (targetId.startsWith("ground-")) {
            const parts = targetId.split("-")[1].split(",");
            if (parts.length === 2) {
                const q = parseInt(parts[0]);
                const r = parseInt(parts[1]);
                const p = HexUtils.toPx(q, r, engine.mapConfig);
                const h = engine.map.getTerrainHeight(q, r);
                return { x: p.x, y: p.y, z: h + 2 };
            }
        }
        return { x: 0, y: 0, z: -9999 };
    }
}

import { Agent } from "../../../../game";
import { AssetManager } from "../../../assets";
import { STATUS_VISUALS } from "../../../../../data/vfx/status_visuals";
import { VisualMath } from "../../../math/VisualMath";

export const OverheadPainter = {
    public draw(ctx: CanvasRenderingContext2D, agent: Agent, x: number, surfaceY: number, t: number) {
        let type = '';
        if (agent.stunTimer > 0) type = 'STUN';
        else if (agent.fearTimer > 0) type = 'FEAR';
        else if (agent.tauntTimer > 0) type = 'TAUNT';
        else if (agent.silenceTimer > 0) type = 'SILENCE';
        else if (agent.blindTimer > 0) type = 'BLIND';

        if (!type) return;

        const icon = AssetManager.getStatusIcon(type);
        if (!icon) return;

        const bob = Math.sin(t * 8) * 4;
        const drawY = VisualMath.getOverheadVisualY(surfaceY, agent.physics.z, bob);

        ctx.save();
        ctx.translate(x, drawY);

        const def = STATUS_VISUALS[type];
        const color = def?.primaryColor || '#fff';

        ctx.shadowColor = color;
        ctx.shadowBlur = 12;
        ctx.globalAlpha = 0.9;
        ctx.drawImage(icon, -20, -20, 40, 40);

        if (type === 'STUN') {
            ctx.rotate(t * 4);
            ctx.fillStyle = '#fff';
            for(let i=0; i<3; i++) {
                const a = i * (Math.PI*2/3);
                ctx.beginPath(); 
                ctx.arc(Math.cos(a)*22, Math.sin(a)*22, 2.5, 0, Math.PI*2); 
                ctx.fill();
            }
        }
        ctx.restore();
    }
};

import { GroundHazard } from "../../../../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../../../../constants";
import { HAZARD_VISUALS } from "../../../../../data/vfx/hazard_visuals";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { SurfacePainter } from "../../../graphics/painters/SurfacePainter";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";
import { VisualMath } from "../../../math/VisualMath";

export const HazardPainter = {
    draw(ctx: CanvasRenderingContext2D, x: number, y: number, hazard: GroundHazard, globalTime: number) {
        const def = HAZARD_VISUALS[hazard.type] || HAZARD_VISUALS['GENERIC'];
        let fade = hazard.duration < 0.8 ? hazard.duration / 0.8 : 1.0;

        ctx.save();
        ctx.globalAlpha = fade;
        const drawY = VisualMath.applyLayerBias(y, 'HAZARD');

        if (def.type === 'FOG') {
            const texture = VFXFactory.getTexture('SMOKE', def.primaryColor);
            const size = HEX_SIZE * 3.0; 
            const speed = globalTime * def.speed;

            ctx.save();
            // SSOT: Use relative layer bias for fog height
            ctx.translate(x, drawY + VisualMath.Z_LAYERS.HAZARD_FOG); 
            ctx.scale(1, ISO_SCALE_Y);

            ctx.globalCompositeOperation = 'source-over';
            ctx.globalAlpha = def.intensity * 0.3;
            ctx.drawImage(texture, -size * 0.3, -size * 0.3, size * 0.6, size * 0.6);

            ctx.globalCompositeOperation = (hazard.type === 'POISON') ? 'screen' : 'lighter';
            ctx.save(); ctx.rotate(speed * 0.12); ctx.globalAlpha = def.intensity * 0.6; ctx.drawImage(texture, -size/2, -size/2, size, size); ctx.restore();
            ctx.save(); ctx.rotate(-speed * 0.08 + 2.0); ctx.scale(0.9, 0.9); ctx.globalAlpha = def.intensity * 0.4; ctx.drawImage(texture, -size/2, -size/2, size, size); ctx.restore();
            ctx.restore();
        }
        else if (def.type === 'LIQUID') {
            const speed = globalTime * def.speed;
            const intensity = def.intensity * (0.85 + Math.sin(speed * 0.8) * 0.15);
            const liquidY = drawY + VisualMath.Z_LAYERS.LIQUID_OFFSET;

            SurfacePainter.drawLiquid(ctx, x, liquidY, def.primaryColor, speed, intensity);
            if (def.cracks) SurfacePainter.drawCracks(ctx, x, liquidY, def.secondaryColor, intensity * 0.8);

            if (hazard.type === 'FIRE') {
                const flameTex = VFXFactory.getTexture('SMOKE', '#fca5a5');
                const rise = (globalTime * 50) % 30;
                ctx.save();
                ctx.translate(x, liquidY - 10 - rise);
                ctx.globalCompositeOperation = 'screen'; ctx.globalAlpha = (1 - rise/30) * intensity;
                ctx.drawImage(flameTex, -20, -60, 40, 60);
                ctx.restore();
            }
        }
        else if (def.type === 'CRYSTAL') {
            if (def.extrude) VolumePainter.drawExtrusion(ctx, x, drawY, HEX_SIZE * 0.8, 8, def.primaryColor, 0.7);
            ctx.save();
            ctx.translate(x, drawY - 5); ctx.scale(1, ISO_SCALE_Y);
            ctx.globalCompositeOperation = 'screen'; ctx.globalAlpha = 0.6;
            ctx.drawImage(VFXFactory.getTexture('ROCK', def.secondaryColor), -15, -15, 30, 30);
            ctx.restore();
        }
        else if (def.type === 'VOID_HOLE') {
            const r = HEX_SIZE * 1.6;
            ctx.save();
            ctx.translate(x, drawY); ctx.scale(1, ISO_SCALE_Y);
            ctx.globalCompositeOperation = 'source-over'; ctx.fillStyle = '#000';
            ctx.beginPath(); ctx.arc(0, 0, r * 0.6, 0, Math.PI*2); ctx.fill();
            ctx.globalCompositeOperation = 'lighter'; ctx.lineWidth = 4; ctx.strokeStyle = def.secondaryColor;
            ctx.shadowColor = def.secondaryColor; ctx.shadowBlur = 20;
            ctx.rotate(globalTime * 3);
            ctx.beginPath();
            for(let i=0; i<3; i++) {
                const ang = i * (Math.PI*2/3); ctx.moveTo(0,0);
                ctx.quadraticCurveTo(Math.cos(ang)*r, Math.sin(ang)*r, Math.cos(ang+1)*r, Math.sin(ang+1)*r);
            }
            ctx.stroke();
            ctx.restore();
        }
        ctx.restore();
    }
};

import { useRef, useState, useCallback, useEffect } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Team, Skill, Role, HexLayout } from '../types';
import { SCENE_DB } from '../data/scenes';
import { DesignExporter } from '../engine/systems/DesignExporter';
import { DEFAULT_HEX_LAYOUT } from '../constants';

export const useGameApp = () => {
    const engineRef = useRef(new GameEngine());

    // 1. Session State (Running Info)
    const [session, setSession] = useState({
        isPlaying: false,
        winner: null as Team | null,
        timeScale: 1.0,
        isShowcaseMode: true,
        transitionPhase: 'IDLE' as 'IDLE' | 'IN' | 'OUT',
        unitCount: 0
    });

    // 2. Editor State (Config & Tools)
    const [editor, setEditor] = useState({
        tool: ToolType.SELECT,
        selectedObstacle: 'WALL',
        hpInput: 600,
        spawnMode: 'RANDOM' as 'RANDOM' | 'DRAFT',
        draftRole: Role.WARRIOR,
        hexLayout: DEFAULT_HEX_LAYOUT,
        mapW: 12,
        mapH: 8,
        currentSceneId: 'VOID'
    });

    // 3. HUD State (Windows & Overlays)
    const [hud, setHud] = useState({
        selectedAgent: null as Agent | null,
        hoveredSkill: null as Skill | null,
        showLogs: false,
        showDB: false,
        showVFXMap: false,
        showFactionWarning: false
    });

    useEffect(() => {
        const engine = engineRef.current;
        const handleGameOver = (data: { winner: Team }) => {
            setSession(prev => ({ ...prev, winner: data.winner, isPlaying: false }));
            if (engine.isRunning) engine.stop(); 
        };
        engine.bus.on('GAME_OVER', handleGameOver);
        return () => engine.bus.off('GAME_OVER', handleGameOver);
    }, []);

    useEffect(() => {
        if (session.isShowcaseMode && session.winner !== null) {
            const timer = setTimeout(() => {
                setSession(prev => ({ ...prev, transitionPhase: 'OUT' }));
                engineRef.current.agents = [];
                engineRef.current.projectiles = [];
                setTimeout(() => {
                    setupShowcaseMap(); 
                    setSession(prev => ({ ...prev, transitionPhase: 'IN' })); 
                    setTimeout(() => {
                        setSession(prev => ({ ...prev, transitionPhase: 'IDLE' }));
                        spawnShowcaseUnits(); 
                    }, 1800);
                }, 1800);
            }, 1000); 
            return () => clearTimeout(timer);
        }
    }, [session.winner, session.isShowcaseMode]);

    const setupShowcaseMap = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setSession(prev => ({ ...prev, winner: null }));
        setHud(prev => ({ ...prev, selectedAgent: null }));
        engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
        engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
        const newLayout: HexLayout = Math.random() > 0.5 ? 'FLAT' : 'POINTY';
        engine.mapConfig.layout = newLayout;
        engine.randomizeEnvironment(); 
        setEditor(prev => ({ ...prev, hexLayout: newLayout, currentSceneId: engine.currentScene.id }));
    }, []);

    const spawnShowcaseUnits = useCallback(() => {
        const engine = engineRef.current;
        let validHexes = Array.from(engine.mapKeys).map(k => {
            const [q, r] = k.split(',').map(Number);
            return {q, r};
        }).filter(h => !engine.map.hasObstacle(h.q, h.r));

        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }

        const roles: Role[] = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];
        let spawnIdx = 0;
        const spawn = (team: Team) => {
            for(let i=0; i<5; i++) {
                if (spawnIdx >= validHexes.length) break;
                const h = validHexes[spawnIdx++];
                engine.addAgent(team, h.q, h.r, 500 + Math.random()*400, roles[i % roles.length]);
            }
        };
        spawn(Team.BLUE); spawn(Team.RED);
        engine.play();
        setSession(prev => ({ ...prev, isPlaying: true }));
    }, []);

    useEffect(() => { setupShowcaseMap(); spawnShowcaseUnits(); }, []);
    useEffect(() => {
        const interval = setInterval(() => setSession(prev => ({ ...prev, unitCount: engineRef.current.agents.length })), 500);
        return () => clearInterval(interval);
    }, []);
    useEffect(() => { engineRef.current.timeScale = session.timeScale; }, [session.timeScale]);

    const enterManualMode = () => {
        engineRef.current.stop();
        engineRef.current.clear(true);
        setSession(prev => ({ ...prev, isShowcaseMode: false, isPlaying: false, winner: null, unitCount: 0 }));
        setEditor(prev => ({ ...prev, mapW: engineRef.current.mapConfig.w, mapH: engineRef.current.mapConfig.h, hexLayout: engineRef.current.mapConfig.layout, currentSceneId: engineRef.current.currentScene.id }));
    };

    return {
        engineRef,
        state: { 
            isShowcaseMode: session.isShowcaseMode, isPlaying: session.isPlaying, unitCount: session.unitCount, winner: session.winner, timeScale: session.timeScale, transitionPhase: session.transitionPhase,
            tool: editor.tool, selectedObstacle: editor.selectedObstacle, hpInput: editor.hpInput, mapW: editor.mapW, mapH: editor.mapH, currentSceneId: editor.currentSceneId, spawnMode: editor.spawnMode, draftRole: editor.draftRole, hexLayout: editor.hexLayout,
            selectedAgent: hud.selectedAgent, hoveredSkill: hud.hoveredSkill, showLogs: hud.showLogs, showDB: hud.showDB, showVFXMap: hud.showVFXMap, showFactionWarning: hud.showFactionWarning
        },
        setters: {
            setTool: (tool: ToolType) => setEditor(p => ({...p, tool})),
            setSelectedObstacle: (selectedObstacle: string) => setEditor(p => ({...p, selectedObstacle})),
            setHpInput: (hpInput: number) => setEditor(p => ({...p, hpInput})),
            setTimeScale: (timeScale: number) => setSession(p => ({...p, timeScale})),
            setSpawnMode: (spawnMode: 'RANDOM' | 'DRAFT') => setEditor(p => ({...p, spawnMode})),
            setDraftRole: (draftRole: Role) => setEditor(p => ({...p, draftRole})),
            setShowLogs: (showLogs: boolean) => setHud(p => ({...p, showLogs})),
            setShowDB: (showDB: boolean) => setHud(p => ({...p, showDB})),
            setShowVFXMap: (showVFXMap: boolean) => setHud(p => ({...p, showVFXMap})),
            setIsShowcaseMode: (isShowcaseMode: boolean) => setSession(p => ({...p, isShowcaseMode})),
            setSelectedAgent: (selectedAgent: Agent | null) => setHud(p => ({...p, selectedAgent})),
            setHoveredSkill: (hoveredSkill: Skill | null) => setHud(p => ({...p, hoveredSkill}))
        },
        actions: {
            enterManualMode,
            handleUpdateMapSize: (w: number, h: number) => { setEditor(p => ({...p, mapW: w, mapH: h})); engineRef.current.mapConfig.w = w; engineRef.current.mapConfig.h = h; engineRef.current.clear(false); },
            handleUpdateLayout: (l: HexLayout) => { setEditor(p => ({...p, hexLayout: l})); engineRef.current.mapConfig.layout = l; engineRef.current.clear(true); },
            handleSetScene: (id: string) => { const s = SCENE_DB.find(x => x.id === id); if(s) { engineRef.current.currentScene = s; engineRef.current.map.rebuildMap(engineRef.current); setEditor(p => ({...p, currentSceneId: id})); } },
            handleRandomBattlefield: () => { engineRef.current.stop(); engineRef.current.randomizeEnvironment(); setSession(p => ({...p, winner: null})); setEditor(p => ({...p, mapW: engineRef.current.mapConfig.w, mapH: engineRef.current.mapConfig.h, currentSceneId: engineRef.current.currentScene.id})); },
            handleReset: () => { engineRef.current.restart(); setSession(p => ({...p, isPlaying: false, winner: null})); },
            togglePlay: () => { 
                if(session.winner) return;
                if(session.isPlaying) { engineRef.current.stop(); setSession(p => ({...p, isPlaying: false})); }
                else {
                    if(engineRef.current.agents.some(a => a.team === Team.BLUE) && engineRef.current.agents.some(a => a.team === Team.RED)) {
                        engineRef.current.play(); setSession(p => ({...p, isPlaying: true}));
                    } else { setHud(p => ({...p, showFactionWarning: true})); setTimeout(() => setHud(p => ({...p, showFactionWarning: false})), 2500); }
                }
            },
            handleNextLevel: () => { engineRef.current.stop(); engineRef.current.randomizeEnvironment(); engineRef.current.play(); setSession(p => ({...p, isPlaying: true, winner: null})); },
            rematch: () => { engineRef.current.restart(); engineRef.current.play(); setSession(p => ({...p, isPlaying: true, winner: null})); },
            startShowcaseMatch: () => { setupShowcaseMap(); spawnShowcaseUnits(); },
            downloadSpec: DesignExporter.downloadSpec,
            handleSelectAgent: (a: Agent | null) => setHud(p => ({...p, selectedAgent: a}))
        }
    };
};

