import { Agent, GameEngine } from "../game";
import { GridSystem } from "../systems/grid";
import { HexUtils, MapConfig } from "../utils";
import { UNIT_BODY_OFFSET, UNIT_HOVER_OFFSET, UNIT_VISUAL_HEIGHT, UNIT_SCALE, VISUAL_ANCHORS } from "../../constants";

export interface Point3D {
    x: number;
    y: number;
    z: number;
}

export class VisualMath {
    public static readonly HORIZON_Y_PCT = 0.62;
    public static readonly PROJECTILE_HIT_TOLERANCE_SQ = 900; 

    public static readonly Z_LAYERS = {
        TERRAIN: 0,
        HAZARD: 3,
        HAZARD_FOG: -15,
        OVERLAY: 5,
        SHADOW: 8,
        UNIT_FEET: 0,
        LIQUID_OFFSET: 1
    };

    /**
     * 計算場景轉場導致的垂直偏置 (SSOT Logic)
     */
    public static getTransitionOffset(x: number, y: number, config: MapConfig, t: number, phase: 'IN' | 'OUT' | 'IDLE'): number {
        if (phase === 'IDLE') return 0;
        const cx = config.offsetX;
        const cy = config.offsetY;
        const dist = Math.sqrt((x - cx)**2 + (y - cy)**2);
        const maxDist = 1000;
        const d = Math.min(1, dist / maxDist);
        const BASE_OFFSET = 1500;
        if (phase === 'OUT') {
            const startT = d * 0.3;
            if (t < startT) return 0;
            let localT = (t - startT) * 1.8;
            localT = Math.max(0, Math.min(1, localT));
            return (localT * localT * (1.5 * localT - 0.5)) * BASE_OFFSET;
        } else if (phase === 'IN') {
            const startT = d * 0.2;
            if (t < startT) return BASE_OFFSET;
            let localT = Math.max(0, Math.min(1, (t - startT) * 1.5));
            return (1 - (1 - Math.pow(1 - localT, 4))) * BASE_OFFSET;
        }
        return 0;
    }

    public static getIsoVisualY(y: number, z: number, extraOffset: number = 0): number {
        return y - z + extraOffset;
    }

    public static getOverheadVisualY(surfaceY: number, z: number, bob: number = 0): number {
        const bodyCenterY = this.getVisualBodyCenterY(surfaceY, z);
        return bodyCenterY - VISUAL_ANCHORS.HEAD_OFFSET_Y - 10 + bob;
    }

    public static applyLayerBias(visualY: number, layer: keyof typeof VisualMath.Z_LAYERS): number {
        return visualY - this.Z_LAYERS[layer];
    }

    public static getVisualBodyCenterY(surfaceY: number, z: number): number {
        return surfaceY - z - UNIT_BODY_OFFSET - UNIT_HOVER_OFFSET;
    }

    public static getUnitAnchor(agent: Agent, engine: GameEngine, grid: GridSystem | null = null): Point3D {
        const terrainH = grid 
            ? grid.getTerrainHeight(agent.q, agent.r, engine) 
            : engine.map.getTerrainHeight(agent.q, agent.r);
        const chestHeight = (UNIT_VISUAL_HEIGHT * 0.45) * UNIT_SCALE;
        const z = terrainH + agent.physics.z + UNIT_BODY_OFFSET + UNIT_HOVER_OFFSET + chestHeight;
        return { x: agent.px + agent.physics.x, y: agent.py + agent.physics.y, z: z };
    }

    public static resolveTargetPoint(targetId: string, engine: GameEngine): Point3D {
        if (!targetId) return { x: 0, y: 0, z: -9999 };
        const agent = engine.agents.find(a => a.id === targetId);
        if (agent) return this.getUnitAnchor(agent, engine);
        if (targetId.startsWith("ground-")) {
            const parts = targetId.split("-")[1].split(",");
            if (parts.length === 2) {
                const q = parseInt(parts[0]);
                const r = parseInt(parts[1]);
                const p = HexUtils.toPx(q, r, engine.mapConfig);
                const h = engine.map.getTerrainHeight(q, r);
                return { x: p.x, y: p.y, z: h + 2 };
            }
        }
        return { x: 0, y: 0, z: -9999 };
    }
}

import { Agent, GameEngine } from "../../game";
import { Projectile, Skill, Team } from "../../../types";
import { HexUtils } from "../../utils";
import { SkillExecutor } from "./SkillExecutor";
import { VisualMath } from "../../math/VisualMath";
import { HazardManager } from "./HazardManager";

export class ProjectileSystem {
    private pool: Projectile[] = [];

    constructor() {
        for (let i = 0; i < 60; i++) this.pool.push(this.createEmptyProjectile());
    }

    public update(dt: number, engine: GameEngine, skillExecutor: SkillExecutor) {
        const list = engine.projectiles;
        for (let i = list.length - 1; i >= 0; i--) {
            const p = list[i];
            if (!p.active) { this.removeProjectile(i, engine); continue; }

            const dtStep = dt / p.totalDuration;
            p.t = Math.min(1.0, p.t + dtStep);

            // 邏輯坐標插值 (作為物理真理)
            p.x = p.startX + (p.endX - p.startX) * p.t;
            p.y = p.startY + (p.endY - p.startY) * p.t;
            p.z = p.startZ + (p.endZ - p.startZ) * p.t;

            if (p.t >= 1.0) {
                this.handleImpact(p, engine, skillExecutor);
                this.release(p);
                this.removeProjectile(i, engine);
            }
        }
    }

    private handleImpact(p: Projectile, engine: GameEngine, skillExecutor: SkillExecutor) {
        const source = engine.agents.find(a => a.id === p.sourceId);
        const hitPos = { x: p.endX, y: p.endY };

        if (p.skill.type === 'AOE') {
            const radius = p.skill.aoeRadius || 1;
            const hitHex = HexUtils.fromPx(hitPos.x, hitPos.y, engine.mapConfig);
            engine.agents.forEach(t => {
                if (t.team !== p.team && t.hp > 0 && !t.banished) {
                    if (HexUtils.dist(hitHex, t) <= radius) {
                        if (source) skillExecutor.resolveHit(source, t, p.skill, hitPos, engine);
                    }
                }
            });
            if (source) HazardManager.spawnHazards(source, HexUtils.range(hitHex, radius), p.skill, engine);
            engine.events.push({ type: 'IMPACT_AOE', pos: hitPos, skill: p.skill, color: p.skill.color });
        } else {
            const target = engine.agents.find(a => a.id === p.targetId);
            if (target && target.hp > 0 && !target.banished) {
                if (source) skillExecutor.resolveHit(source, target, p.skill, undefined, engine);
            }
        }
        engine.events.push({ type: 'PROJECTILE_HIT', pos: hitPos, skill: p.skill });
    }

    private removeProjectile(idx: number, engine: GameEngine) {
        const last = engine.projectiles.pop();
        if (last && idx < engine.projectiles.length) engine.projectiles[idx] = last;
    }

    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        const target = skill.type === 'AOE' ? (source.targetHex || source.target) : source.target;
        if (!target) return;

        const targetId = (target as any).id || `ground-${(target as any).q},${(target as any).r}`;
        const launchPoint = VisualMath.getUnitAnchor(source, engine);
        const targetPoint = VisualMath.resolveTargetPoint(targetId, engine);

        const dx = targetPoint.x - launchPoint.x;
        const dy = targetPoint.y - launchPoint.y;
        const totalDist = Math.sqrt(dx*dx + dy*dy);
        const speed = skill.projectileSpeed || 800;

        const p = this.pool.pop() || this.createEmptyProjectile();
        p.active = true;
        p.id = Math.random().toString(36).substr(2, 6);
        p.sourceId = source.id;
        p.team = source.team;
        p.skill = skill;
        p.t = 0;
        p.totalDuration = Math.max(0.1, totalDist / speed);
        p.startX = launchPoint.x; p.startY = launchPoint.y; p.startZ = launchPoint.z;
        p.endX = targetPoint.x; p.endY = targetPoint.y; p.endZ = targetPoint.z;
        p.totalDist = totalDist;
        p.targetId = targetId;
        p.trail = [];

        engine.projectiles.push(p);
        engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill, targetId });
    }

    private release(p: Projectile) { p.active = false; p.trail = []; this.pool.push(p); }

    private createEmptyProjectile(): Projectile {
        return { 
            id: '', active: false, createdAt: 0, lifespan: 0, 
            x: 0, y: 0, z: 0, t: 0, totalDuration: 0,
            startX: 0, startY: 0, startZ: 0, endX: 0, endY: 0, endZ: 0, totalDist: 0,
            targetId: '', targetPos: {x: 0, y: 0}, 
            speed: 0, skill: {} as Skill, sourceId: '', team: Team.BLUE, trail: [] 
        };
    }
}

import { GameEngine } from "../../../game";
import { RenderList, RenderOpType } from "../../../renderers/RenderList";
import { PROJECTILE_VISUALS, DEFAULT_PROJECTILE, ProjectileVisualDef } from "../../../../data/vfx/projectile_visuals";
import { TrajectoryMath, Point3D } from "../../../math/TrajectoryMath";
import { VisualMath } from "../../../math/VisualMath";

export const ProjectileRenderer = {
    submit(
        renderList: RenderList,
        engine: GameEngine,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        for (const p of engine.projectiles) {
            if (!p.active) continue;

            const def: ProjectileVisualDef = PROJECTILE_VISUALS[p.skill.visualProjectileEffect || p.skill.visual || 'BOLT'] || DEFAULT_PROJECTILE;

            // 起點與終點來自 Projectile SSOT
            const startP: Point3D = { x: p.startX, y: p.startY, z: p.startZ };
            const endP: Point3D = { x: p.endX, y: p.endY, z: p.endZ };

            const getPosAt = (progress: number) => {
                if (def.trajectory === 'ARC') {
                    const arcH = Math.min(def.arcHeight || 150, Math.max(30, p.totalDist * 0.35));
                    return TrajectoryMath.parabolic(startP, endP, progress, arcH);
                }
                if (def.trajectory === 'WOBBLE') return TrajectoryMath.wobble(startP, endP, progress, def.wobbleAmp || 15, def.wobbleFreq || 2);
                return TrajectoryMath.linear(startP, endP, progress);
            };

            const current3D = getPosAt(p.t);
            const visAngle = TrajectoryMath.getProjectedAngle(getPosAt, p.t, 1.0);

            // 轉場偏置統合至 VisualMath
            const transOffset = VisualMath.getTransitionOffset(current3D.x, current3D.y, engine.mapConfig, transitionT, transitionPhase);
            const visY = VisualMath.getIsoVisualY(current3D.y, current3D.z) + transOffset;

            const op = renderList.next();
            op.type = RenderOpType.PROJECTILE;
            op.y = current3D.y; 
            op.z = 5000 + current3D.z; 

            op.pVisX = current3D.x;
            op.pVisY = visY;
            op.pAngle = visAngle;
            op.pSkillVis = def.spriteKey || p.skill.visual || 'BOLT';
            op.pColor = p.skill.color;
            op.pIsUlt = p.skill.tag === 'ULT';
            op.pSpin = def.spinSpeed ? (p.t * p.totalDuration * def.spinSpeed) : 0;
            op.pScale = def.scale || 1.0; 

            op.pTrail = [];
            const trailSamples = def.trailLength || 0;
            if (trailSamples > 0) {
                const step = 0.015; 
                for (let j = 1; j <= trailSamples; j++) {
                    const tPast = Math.max(0, p.t - j * step);
                    const past3D = getPosAt(tPast);
                    const pOffset = VisualMath.getTransitionOffset(past3D.x, past3D.y, engine.mapConfig, transitionT, transitionPhase);
                    const pastY = VisualMath.getIsoVisualY(past3D.y, past3D.z) + pOffset;
                    op.pTrail.push({ x: past3D.x, y: pastY });
                    if (tPast <= 0) break;
                }
            }
        }
    }
};

import { Agent } from "../../game";
import { MapConfig } from "../../utils";

export interface UnitVisualState {
    agent: Agent;
    x: number;
    y: number;
    z: number;
    terrainHeight: number;
    scale: number;
    isSilhouette: boolean;
    isSelected: boolean;
    sortY: number;
    isDead: boolean;
    isVisible: boolean;
}

export class UnitVisualProcessor {
    public static process(
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        highlightAgent: Agent | null
    ): UnitVisualState {
        const isDead = agent.hp <= 0;
        const visualX = agent.px + agent.physics.x;
        const visualY = agent.py + agent.physics.y;

        // 核心：使用邏輯網格位置作為高度真理
        const terrainH = getTerrainHeight(agent.q, agent.r);
        const isSelected = (agent === highlightAgent);

        return {
            agent,
            x: visualX,
            y: visualY,
            z: agent.physics.z,
            terrainHeight: terrainH,
            scale: 1.0, 
            isSilhouette: false,
            isSelected,
            sortY: agent.py, 
            isDead,
            isVisible: !agent.fullyDead
        };
    }
}

import { GameEngine, Agent } from "../../game";
import { GridCache } from "./GridCache";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { Hex, Skill, Projectile } from "../../../types";
import { TERRAIN_THEMES, HEX_SIZE } from "../../../constants";
import { HexUtils } from "../../utils";
import { VisualMath } from "../../math/VisualMath";

const OBSTACLE_Z_INDEX = 10;
const PROJ_LIGHT_RADIUS_SQ = 1600;

export class GridRenderStrategy {

    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    public submit(
        cache: GridCache,
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        if (transitionPhase === 'OUT' && transitionT > 0.95) return;

        cache.ensure(engine);
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];
        const layout = engine.mapConfig.layout;

        this._unitPresence.clear();
        this._unitVisualStatus.clear();
        for (const a of engine.agents) {
            if (a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') this._unitVisualStatus.set(key, a.visualStatus);
            }
        }

        const len = cache.tileList.length;
        for (let i = 0; i < len; i++) {
            const tile = cache.tileList[i];
            const { q, r, px, py, h, key } = tile;

            const offset = VisualMath.getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);
            const visualBaseY = py + offset;
            const visualSurfaceY = VisualMath.getIsoVisualY(visualBaseY, h);

            if (Math.abs(offset) > 800) continue;

            const obstacleType = engine.obstacles.get(key);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.tq = q; op.tr = r; op.th = h; 
                op.tx = px; op.ty = visualSurfaceY; 
                op.ttype = obstacleType;
            }

            const hazard = engine.map.getHazardAt(q, r, engine);
            if (hazard) {
                const hOp = renderList.next();
                hOp.type = RenderOpType.HAZARD;
                hOp.tq = q; hOp.tr = r; hOp.th = h;
                hOp.tx = px; hOp.ty = visualSurfaceY; 
                hOp.oHazard = hazard;
                hOp.time = globalTime;
            }

            const zoneInfo = engine.zones.getZoneAt(q, r);
            let isRange = false;
            let rangeColor = '';
            if (hoveredSkill && highlightAgent) {
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const deltaH = agentH - h;
                const bonus = Math.max(0, Math.floor(deltaH / 24)); 
                const dist = HexUtils.dist({q, r}, {q: highlightAgent.q, r: highlightAgent.r});
                if (dist <= hoveredSkill.range + bonus) { isRange = true; rangeColor = hoveredSkill.color; }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;
            const hasUnit = !engine.isRunning && this._unitPresence.has(key);

            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.tq = q; op.tr = r; op.th = h;
            op.tx = px; op.ty = visualBaseY; 
            op.tsize = HEX_SIZE; op.ttheme = theme; op.ttype = scene.textureType; op.tdetail = theme.detail;
            op.oStatus = this._unitVisualStatus.get(key);
            op.oDanger = zoneInfo; 
            op.oRange = isRange; op.oRangeCol = rangeColor;
            op.oHover = isHover; op.oHasUnit = hasUnit;
            op.time = globalTime;
        }
    }
}

import { Agent, GameEngine } from "../game";
import { GridSystem } from "../systems/grid";
import { HexUtils, MapConfig } from "../utils";
import { UNIT_BODY_OFFSET, UNIT_HOVER_OFFSET, UNIT_VISUAL_HEIGHT, UNIT_SCALE, VISUAL_ANCHORS } from "../../constants";

export interface Point3D {
    x: number;
    y: number;
    z: number;
}

export class VisualMath {
    public static readonly HORIZON_Y_PCT = 0.62;
    public static readonly PROJECTILE_HIT_TOLERANCE_SQ = 900; 

    public static readonly Z_LAYERS = {
        TERRAIN: 0,
        HAZARD: 3,
        HAZARD_FOG: -15,
        OVERLAY: 5,
        SHADOW: 8,
        UNIT_FEET: 0,
        LIQUID_OFFSET: 1
    };

    /**
     * 計算場景轉場導致的垂直偏置 (SSOT Logic)
     */
    public static getTransitionOffset(x: number, y: number, config: MapConfig, t: number, phase: 'IN' | 'OUT' | 'IDLE'): number {
        if (phase === 'IDLE') return 0;
        const cx = config.offsetX;
        const cy = config.offsetY;
        const dist = Math.sqrt((x - cx)**2 + (y - cy)**2);
        const maxDist = 1000;
        const d = Math.min(1, dist / maxDist);
        const BASE_OFFSET = 1500;
        if (phase === 'OUT') {
            const startT = d * 0.3;
            if (t < startT) return 0;
            let localT = (t - startT) * 1.8;
            localT = Math.max(0, Math.min(1, localT));
            return (localT * localT * (1.5 * localT - 0.5)) * BASE_OFFSET;
        } else if (phase === 'IN') {
            const startT = d * 0.2;
            if (t < startT) return BASE_OFFSET;
            let localT = Math.max(0, Math.min(1, (t - startT) * 1.5));
            return (1 - (1 - Math.pow(1 - localT, 4))) * BASE_OFFSET;
        }
        return 0;
    }

    public static getIsoVisualY(y: number, z: number, extraOffset: number = 0): number {
        return y - z + extraOffset;
    }

    /**
     * Helper for entity-based HUD/VFX positioning.
     * Combines logical Y, terrain height, and physical offsets.
     */
    public static getEntityVisualY(logicalY: number, terrainH: number, physY: number, physZ: number, extraOffset: number = 0): number {
        const surfaceY = (logicalY + physY) - terrainH;
        return this.getIsoVisualY(surfaceY, physZ, extraOffset);
    }

    public static getOverheadVisualY(surfaceY: number, z: number, bob: number = 0): number {
        const bodyCenterY = this.getVisualBodyCenterY(surfaceY, z);
        return bodyCenterY - VISUAL_ANCHORS.HEAD_OFFSET_Y - 10 + bob;
    }

    public static applyLayerBias(visualY: number, layer: keyof typeof VisualMath.Z_LAYERS): number {
        return visualY - this.Z_LAYERS[layer];
    }

    public static getVisualBodyCenterY(surfaceY: number, z: number): number {
        return surfaceY - z - UNIT_BODY_OFFSET - UNIT_HOVER_OFFSET;
    }

    public static getUnitAnchor(agent: Agent, engine: GameEngine, grid: GridSystem | null = null): Point3D {
        const terrainH = grid 
            ? grid.getTerrainHeight(agent.q, agent.r, engine) 
            : engine.map.getTerrainHeight(agent.q, agent.r);
        const chestHeight = (UNIT_VISUAL_HEIGHT * 0.45) * UNIT_SCALE;
        const z = terrainH + agent.physics.z + UNIT_BODY_OFFSET + UNIT_HOVER_OFFSET + chestHeight;
        return { x: agent.px + agent.physics.x, y: agent.py + agent.physics.y, z: z };
    }

    public static resolveTargetPoint(targetId: string, engine: GameEngine): Point3D {
        if (!targetId) return { x: 0, y: 0, z: -9999 };
        // Corrected variable reference from agentId to targetId
        const agent = engine.agents.find(a => a.id === targetId);
        if (agent) return this.getUnitAnchor(agent, engine);
        if (targetId.startsWith("ground-")) {
            const parts = targetId.split("-")[1].split(",");
            if (parts.length === 2) {
                const q = parseInt(parts[0]);
                const r = parseInt(parts[1]);
                const p = HexUtils.toPx(q, r, engine.mapConfig);
                const h = engine.map.getTerrainHeight(q, r);
                return { x: p.x, y: p.y, z: h + 2 };
            }
        }
        return { x: 0, y: 0, z: -9999 };
    }
}

