export const VICTORY_PHASE_DURATION = 0.5; 

export class GameEngine {
    public agents: Agent[] = [];
    public projectiles: Projectile[] = [];

    public state = {
        director: { focusTimer: 0, priorityTimer: 0, targetId: null as string | null },
        hazards: new Map<string, GroundHazard>(),
        victory: { victoryTimer: 0, winningTeam: null as Team | null, isFinishing: false },
        time: { battleTime: 0, timeScale: 1.0, targetTimeScale: 1.0 }
    };

    public sessionState: GlobalSessionState = {
        killStreaks: new Map(),
        firstBloodTriggered: false,
        directorTargetId: null,
        directorTimer: 0,
        directorPriorityTimer: 0
    };

    get hazards() { return this.state.hazards; }
    get battleTime() { return this.state.time.battleTime; }
    set battleTime(v: number) { this.state.time.battleTime = v; }
    get timeScale() { return this.state.time.timeScale; }
    set timeScale(v: number) { this.state.time.timeScale = v; }
    get targetTimeScale() { return this.state.time.targetTimeScale; }
    set targetTimeScale(v: number) { this.state.time.targetTimeScale = v; }
    get victory() { return this.state.victory; }

    get directorTargetId() { return this.state.director.targetId; }
    get mapKeys() { return this.map.mapKeys; }
    get obstacles() { return this.map.obstacles; }
    get agentMap() { return this.map.agentMap; }
    get logs() { return this.logger.logs; }

    public events: GameEvent[] = [];
    public bus: EventBus = new EventBus();
    public renderer?: GameRenderer;
    public isRunning: boolean = false;
    public mapVersion: number = 0; 

    public mapConfig: MapConfig = { w: 12, h: 8, offsetX: 0, offsetY: 0, layout: DEFAULT_HEX_LAYOUT };
    public currentScene: SceneTheme = SCENE_DB[0];
    public skillDB: Skill[] = [...DEFAULT_SKILL_DB];

    public movement: MovementSystem = new MovementSystem();
    public physics: PhysicsSystem = new PhysicsSystem(); 
    public combat: CombatSystem = new CombatSystem();
    public map: MapSystem = new MapSystem();
    public hazardSystem: HazardSystem = new HazardSystem();
    public ai: AISystem = new AISystem();
    public agentManager: AgentManager = new AgentManager();
    public announcer: AnnouncerSystem = new AnnouncerSystem(); 
    public director: DirectorSystem = new DirectorSystem();
    public logger: BattleLogger = new BattleLogger(); 
    public victorySystem: VictorySystem = new VictorySystem(); 
    public zones: ZoneSystem = new ZoneSystem(); 
    public cooldowns: CooldownSystem = new CooldownSystem();
    public effects: EffectSystem = new EffectSystem();
    public controls: ControlSystem = new ControlSystem();
    public timeSystem: TimeSystem = new TimeSystem();

    constructor() {
        this.map.randomizeEnvironment(this);
    }

    public addAgent(team: Team, q: number, r: number, hpOverride?: number, roleOverride?: Role) { 
        return this.agentManager.addAgent(this, team, q, r, hpOverride, roleOverride); 
    }
    public isValid(q: number, r: number) { return this.map.isValid(q, r); }
    public isBlocked(q: number, r: number, ignoreId?: string, movementType: MovementType = MovementType.GROUND) { return this.map.isBlocked(q, r, this, ignoreId, movementType); }
    public isValidHash(h: number) { return this.map.isValidHash(h); }
    public hasObstacle(q: number, r: number) { return this.map.hasObstacle(q, r); }
    public hasObstacleHash(h: number) { return this.map.hasObstacleHash(h); }
    public getTerrainHeight(q: number, r: number) { return this.map.getTerrainHeight(q, r); }

    public randomizeEnvironment() { 
        this.state.hazards.clear(); 
        if (this.renderer) this.renderer.vfx.reset(); 
        this.map.randomizeEnvironment(this); 
    }

    public rebuildMap() { 
        this.state.hazards.clear();
        this.map.rebuildMap(this); 
    }

    public removeAgent(q: number, r: number) {
        const agent = this.map.getAgentAt(q, r);
        if (agent) {
            this.agents = this.agents.filter(a => a !== agent);
            this.map.unregisterAgent(agent);
        }
    }

    public getAgentAt(q: number, r: number): Agent | undefined {
        return this.map.getAgentAt(q, r);
    }

    public updateAgentPosition(agent: Agent, newQ: number, newR: number) {
        this.map.updateAgentPosition(agent, newQ, newR);
    }

    public pushEvent(type: GameEventType, pos: {x: number, y: number}, opts: any = {}) {
        const evt = EventPool.get(type, pos, opts);
        if (type === 'KILL' && opts.sourceId) {
            this.director.forceFocus(this, opts.sourceId, 2.5);
        } else if (type === 'CAST_START' && opts.skill?.tag === 'ULT' && opts.sourceId) {
            this.director.forceFocus(this, opts.sourceId, 3.5); 
        }
        this.events.push(evt);
    }

    public play() {
        if (!this.isRunning) {
            this.agents.forEach(a => a.saveState());
            this.state.time.battleTime = 0;
            this.logger.clear();
            this.victorySystem.reset(this);
            this.sessionState.killStreaks.clear();
            this.sessionState.firstBloodTriggered = false;
            this.log(null, 'SYSTEM', '開始', null, '戰鬥分析開始');
            this.bus.emit('GAME_START', {});
        }
        this.map.clearAgents();
        this.agents.forEach(a => {
            a.skills = a.skillIds.map(id => this.skillDB.find(s => s.id === id) || null);
            a.bt = this.ai.buildAI(a, this); 
            a.animState = AnimState.IDLE;
            if (a.hp > 0) this.map.registerAgent(a);
        });
        this.isRunning = true;
    }

    public stop() { this.isRunning = false; }

    public restart() {
        this.stop();
        this.victorySystem.reset(this);
        this.state.time.battleTime = 0;
        this.map.clearAgents();
        this.state.hazards.clear(); 
        this.director.reset(this);
        this.sessionState.killStreaks.clear();
        this.sessionState.firstBloodTriggered = false;
        this.agents.forEach(a => {
            a.reset(this.mapConfig);
            a.skills = a.skillIds.map(id => this.skillDB.find(s => s.id === id) || null);
            this.map.registerAgent(a);
        });
        this.projectiles = [];
        if (this.renderer) {
            this.renderer.reset();
            this.renderer.grid.reset(); 
            this.renderer.vfx.reset(); 
        }
        this.log(null, 'SYSTEM', '重置', null, '戰場狀態已重置');
        this.bus.emit('GAME_RESET', {});
    }

    public clear(keepScene: boolean = false) {
        this.stop();
        this.agents = [];
        this.projectiles = [];
        this.map.clearAgents();
        this.state.hazards.clear(); 
        this.map.obstacles.clear();
        this.map.obstaclesHash.clear();
        this.director.reset(this);
        this.logger.clear();

        // 核心修復：清除跨局序列動作
        SequenceSystem.clear(); 

        if (this.renderer) {
            this.renderer.reset();
            this.renderer.grid.reset();
            this.renderer.vfx.reset();
        }
        if (!keepScene) this.map.randomizeEnvironment(this); 
        else this.map.rebuildMap(this); 
        this.bus.emit('GAME_CLEAR', {});
    }

    public tick(dt: number) {
        if (!this.isRunning) return;
        this.timeSystem.update(dt, this);
        this.events.length = 0; 
        this.director.update(this, dt);
        this.zones.update(this); 
        if (this.victorySystem.check(this)) {
            this.victorySystem.updateFinishing(dt, this);
            this.updateEntities(dt);
            return;
        }
        this.updateEntities(dt);
    }

    private updateEntities(dt: number) {
        this.physics.update(dt, this);
        for (const a of this.agents) {
            if (a.hitFlashTimer > 0) a.hitFlashTimer -= dt;
            if (a.hp <= 0) {
                this.agentManager.handleDeadState(a, this);
                continue;
            }
            this.cooldowns.update(a, dt);
            this.effects.update(a, dt, this);
            this.controls.update(a, dt, this);
            if (a.isMoving && a.path.length > 0 && a.stunTimer <= 0) {
                this.movement.updateMovement(a, dt, this);
            }
            if (a.bt) {
                const resetTree = (node: BTNode) => { 
                    node.status = null; 
                    if (node.c) node.c.forEach(resetTree); 
                };
                resetTree(a.bt);
                a.bt.tick(a);
            }
        }
        this.combat.update(dt, this);
        this.hazardSystem.update(dt, this); 
        this.movement.resolveStacking(this);
        this.announcer.update(dt, this);
    }

    public log(agent: Agent | null, type: LogActionType, actionName: string, targetInfo: string | null, detail: string = '') {
        this.logger.log(this.battleTime, this.battleTime * 10, agent, type, actionName, targetInfo, detail);
    }

    public getEffectiveRange(a: Hex, targetQ: number, targetR: number, baseRange: number): number {
        return this.movement.getEffectiveRange(a, targetQ, targetR, baseRange, this);
    }

    public calculateOptimalTarget(source: Agent, skill: Skill) {
        return this.movement.calculateOptimalTarget(source, skill, this);
    }

    public moveAgentToHex(a: Agent, targetHex: Hex, r: number, speedMult: number = 1.0): NodeState {
        return this.movement.moveAgentToHex(a, targetHex, r, this, speedMult);
    }

    public initiateCast(a: Agent, skillIdx: number): NodeState {
        return this.combat.initiateCast(a, skillIdx, this);
    }

    public updateTarget(a: Agent) {
        this.movement.updateTarget(a, this);
    }
}

import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { Point3D } from "./EventVFXMapper";
import { VFXSequence, VFXAction } from "../../../types/VFXSchema";
import { VisualMath } from "../../math/VisualMath";

interface QueuedAction {
    executeAt: number;
    action: VFXAction;
    target: Point3D;
    source?: Point3D;
}

export class SequenceSystem {
    private static actionQueue: QueuedAction[] = [];

    public static clear() {
        this.actionQueue = [];
    }

    public static run(
        sequence: VFXSequence,
        target: Point3D,
        engine: GameEngine,
        vfx: VFXSystem,
        sourceId?: string
    ) {
        let sourcePos: Point3D | undefined;
        if (sourceId) {
            const agent = engine.agents.find(a => a.id === sourceId);
            if (agent) sourcePos = VisualMath.getUnitAnchor(agent, engine);
        }

        const baseTime = engine.battleTime;
        sequence.actions.forEach(action => {
            const executeAt = baseTime + (action.delay || 0);
            if (executeAt <= baseTime) {
                this.dispatch(action, target, sourcePos, vfx, engine);
            } else {
                this.actionQueue.push({ executeAt, action, target, source: sourcePos });
            }
        });
    }

    public static update(engine: GameEngine, vfx: VFXSystem) {
        const now = engine.battleTime;
        for (let i = this.actionQueue.length - 1; i >= 0; i--) {
            const item = this.actionQueue[i];
            if (now >= item.executeAt) {
                this.dispatch(item.action, item.target, item.source, vfx, engine);
                this.actionQueue.splice(i, 1);
            }
        }
    }

    private static dispatch(action: VFXAction, target: Point3D, source: Point3D | undefined, vfx: VFXSystem, engine: GameEngine) {
        const effectId = action.id || 'FX_HIT_GENERIC';
        const groundZ = target.z - 2; 

        switch (action.type) {
            case 'PARTICLE':
                vfx.playEffect(effectId, target.x, target.y, target.z, action.color, groundZ);
                break;
            case 'BEAM':
                if (source) vfx.playBeam(action.style || 'GENERIC_BEAM', source, target, action.color, action.duration || 0.4);
                break;
            case 'SHAKE':
                if (engine.renderer) engine.renderer.camera.addTrauma(action.shakeIntensity || 0.3);
                break;
            case 'GRID_PULSE':
                vfx.playEffect(action.color?.includes('#3b') ? 'FX_GRID_IMPACT_BLUE' : 'FX_GRID_IMPACT_RED', target.x, target.y, groundZ + 4, action.color, groundZ);
                break;
            case 'HEAVEN_FALL':
                const h = action.height || 1200;
                const p = vfx.state.getParticle();
                p.x = target.x; p.y = target.y; p.z = target.z + h;
                p.vz = -3500;
                p.life = (h / 3500) + 0.1; 
                p.maxLife = p.life;
                p.color = action.color || '#fff';
                p.size = (action.scale || 1.8) * 80;
                p.type = action.style === 'METEOR' ? 'ROCK' : 'GIANT_HEX';
                p.locked = false;
                (p as any).pIsUlt = true; 
                vfx.state.particles.push(p);
                break;
        }
    }
}

import { useRef, useState, useCallback, useEffect } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Team, Skill, Role, HexLayout } from '../types';
import { SCENE_DB } from '../data/scenes';
import { DesignExporter } from '../engine/systems/DesignExporter';
import { DEFAULT_HEX_LAYOUT } from '../constants';

export const useGameApp = () => {
    const engineRef = useRef(new GameEngine());

    const [session, setSession] = useState({
        isPlaying: false,
        winner: null as Team | null,
        timeScale: 1.0,
        isShowcaseMode: true,
        transitionPhase: 'IDLE' as 'IDLE' | 'IN' | 'OUT',
        unitCount: 0
    });

    const [editor, setEditor] = useState({
        tool: ToolType.SELECT,
        selectedObstacle: 'WALL',
        hpInput: 600,
        spawnMode: 'RANDOM' as 'RANDOM' | 'DRAFT',
        draftRole: Role.WARRIOR,
        hexLayout: DEFAULT_HEX_LAYOUT,
        mapW: 12,
        mapH: 8,
        currentSceneId: 'VOID'
    });

    const [hud, setHud] = useState({
        selectedAgent: null as Agent | null,
        hoveredSkill: null as Skill | null,
        showLogs: false,
        showDB: false,
        showVFXMap: false,
        showFactionWarning: false
    });

    // 核心邏輯：內部統一單位生成器
    const internalSpawnTeams = useCallback(() => {
        const engine = engineRef.current;
        // 確保地圖已重建並獲取有效格子
        let validHexes = Array.from(engine.mapKeys).map(k => {
            const [q, r] = k.split(',').map(Number);
            return {q, r};
        }).filter(h => !engine.map.hasObstacle(h.q, h.r));

        // 洗牌確保位置隨機
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }

        const roles: Role[] = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];
        let spawnIdx = 0;

        const spawn = (team: Team) => {
            for(let i=0; i<5; i++) {
                if (spawnIdx >= validHexes.length) break;
                const h = validHexes[spawnIdx++];
                engine.addAgent(team, h.q, h.r, 600 + Math.random()*400, roles[i % roles.length]);
            }
        };

        spawn(Team.BLUE); 
        spawn(Team.RED);
        setSession(prev => ({ ...prev, unitCount: engine.agents.length }));
    }, []);

    useEffect(() => {
        const engine = engineRef.current;
        const handleGameOver = (data: { winner: Team }) => {
            setSession(prev => ({ ...prev, winner: data.winner, isPlaying: false }));
            if (engine.isRunning) engine.stop(); 
        };
        engine.bus.on('GAME_OVER', handleGameOver);
        return () => engine.bus.off('GAME_OVER', handleGameOver);
    }, []);

    const spawnShowcaseUnits = useCallback(() => {
        const engine = engineRef.current;
        engine.clear(true); 
        internalSpawnTeams();
        engine.play();
        setSession(prev => ({ ...prev, isPlaying: true, winner: null }));
    }, [internalSpawnTeams]);

    const setupShowcaseMap = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setHud(prev => ({ ...prev, selectedAgent: null }));
        engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
        engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
        const newLayout: HexLayout = Math.random() > 0.5 ? 'FLAT' : 'POINTY';
        engine.mapConfig.layout = newLayout;
        engine.randomizeEnvironment(); 
        setEditor(prev => ({ ...prev, hexLayout: newLayout, currentSceneId: engine.currentScene.id }));
    }, []);

    useEffect(() => {
        if (session.isShowcaseMode && session.winner !== null) {
            const timer = setTimeout(() => {
                setSession(prev => ({ ...prev, transitionPhase: 'OUT' }));
                setTimeout(() => {
                    setupShowcaseMap(); 
                    setSession(prev => ({ ...prev, transitionPhase: 'IN' })); 
                    setTimeout(() => {
                        setSession(prev => ({ ...prev, transitionPhase: 'IDLE' }));
                        spawnShowcaseUnits(); 
                    }, 1500);
                }, 1200);
            }, 2000);
            return () => clearTimeout(timer);
        }
    }, [session.winner, session.isShowcaseMode, setupShowcaseMap, spawnShowcaseUnits]);

    useEffect(() => { 
        setupShowcaseMap(); 
        spawnShowcaseUnits(); 
    }, []);

    useEffect(() => {
        const interval = setInterval(() => setSession(prev => ({ ...prev, unitCount: engineRef.current.agents.length })), 500);
        return () => clearInterval(interval);
    }, []);

    useEffect(() => { engineRef.current.timeScale = session.timeScale; }, [session.timeScale]);

    const enterManualMode = () => {
        engineRef.current.stop();
        engineRef.current.clear(true);
        setSession(prev => ({ ...prev, isShowcaseMode: false, isPlaying: false, winner: null, unitCount: 0 }));
        setEditor(prev => ({ 
            ...prev, 
            mapW: engineRef.current.mapConfig.w, 
            mapH: engineRef.current.mapConfig.h, 
            hexLayout: engineRef.current.mapConfig.layout, 
            currentSceneId: engineRef.current.currentScene.id 
        }));
    };

    return {
        engineRef,
        state: { 
            isShowcaseMode: session.isShowcaseMode, isPlaying: session.isPlaying, unitCount: session.unitCount, winner: session.winner, timeScale: session.timeScale, transitionPhase: session.transitionPhase,
            tool: editor.tool, selectedObstacle: editor.selectedObstacle, hpInput: editor.hpInput, mapW: editor.mapW, mapH: editor.mapH, currentSceneId: editor.currentSceneId, spawnMode: editor.spawnMode, draftRole: editor.draftRole, hexLayout: editor.hexLayout,
            selectedAgent: hud.selectedAgent, hoveredSkill: hud.hoveredSkill, showLogs: hud.showLogs, showDB: hud.showDB, showVFXMap: hud.showVFXMap, showFactionWarning: hud.showFactionWarning
        },
        setters: {
            setTool: (tool: ToolType) => setEditor(p => ({...p, tool})),
            setSelectedObstacle: (selectedObstacle: string) => setEditor(p => ({...p, selectedObstacle})),
            setHpInput: (hpInput: number) => setEditor(p => ({...p, hpInput})),
            setTimeScale: (timeScale: number) => setSession(p => ({...p, timeScale})),
            setSpawnMode: (spawnMode: 'RANDOM' | 'DRAFT') => setEditor(p => ({...p, spawnMode})),
            setDraftRole: (draftRole: Role) => setEditor(p => ({...p, draftRole})),
            setShowLogs: (showLogs: boolean) => setHud(p => ({...p, showLogs})),
            setShowDB: (showDB: boolean) => setHud(p => ({...p, showDB})),
            setShowVFXMap: (showVFXMap: boolean) => setHud(p => ({...p, showVFXMap})),
            setIsShowcaseMode: (isShowcaseMode: boolean) => setSession(p => ({...p, isShowcaseMode})),
            setSelectedAgent: (selectedAgent: Agent | null) => setHud(p => ({...p, selectedAgent})),
            setHoveredSkill: (hoveredSkill: Skill | null) => setHud(p => ({...p, hoveredSkill}))
        },
        actions: {
            enterManualMode,
            handleUpdateMapSize: (w: number, h: number) => { setEditor(p => ({...p, mapW: w, mapH: h})); engineRef.current.mapConfig.w = w; engineRef.current.mapConfig.h = h; engineRef.current.clear(true); },
            handleUpdateLayout: (l: HexLayout) => { setEditor(p => ({...p, hexLayout: l})); engineRef.current.mapConfig.layout = l; engineRef.current.clear(true); },
            handleSetScene: (id: string) => { const s = SCENE_DB.find(x => x.id === id); if(s) { engineRef.current.currentScene = s; engineRef.current.map.rebuildMap(engineRef.current); setEditor(p => ({...p, currentSceneId: id})); } },
            handleRandomBattlefield: () => { 
                engineRef.current.stop(); 
                engineRef.current.clear(true);
                engineRef.current.randomizeEnvironment(); 
                internalSpawnTeams(); // 手動隨機也重新生成單位
                setSession(p => ({...p, winner: null})); 
                setEditor(p => ({...p, mapW: engineRef.current.mapConfig.w, mapH: engineRef.current.mapConfig.h, currentSceneId: engineRef.current.currentScene.id})); 
            },
            handleReset: () => { engineRef.current.restart(); setSession(p => ({...p, isPlaying: false, winner: null})); },
            togglePlay: () => { 
                if(session.winner) return;
                if(session.isPlaying) { engineRef.current.stop(); setSession(p => ({...p, isPlaying: false})); }
                else {
                    if(engineRef.current.agents.some(a => a.team === Team.BLUE) && engineRef.current.agents.some(a => a.team === Team.RED)) {
                        engineRef.current.play(); setSession(p => ({...p, isPlaying: true}));
                    } else { setHud(p => ({...p, showFactionWarning: true})); setTimeout(() => setHud(p => ({...p, showFactionWarning: false})), 2500); }
                }
            },
            handleNextLevel: () => { 
                engineRef.current.stop(); 
                engineRef.current.clear(true); 
                engineRef.current.randomizeEnvironment(); 
                internalSpawnTeams(); // 下一關自動生成單位
                setSession(p => ({...p, isPlaying: false, winner: null})); 
            },
            rematch: () => { engineRef.current.restart(); engineRef.current.play(); setSession(p => ({...p, isPlaying: true, winner: null})); },
            startShowcaseMatch: () => { setupShowcaseMap(); spawnShowcaseUnits(); },
            downloadSpec: DesignExporter.downloadSpec,
            handleSelectAgent: (a: Agent | null) => setHud(p => ({...p, selectedAgent: a}))
        }
    };
};

