import { useRef, useState, useCallback, useEffect } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Team, Skill, Role, HexLayout } from '../types';
import { SCENE_DB } from '../data/scenes';
import { DesignExporter } from '../engine/systems/DesignExporter';
import { DEFAULT_HEX_LAYOUT } from '../constants';

export const useGameApp = () => {
    const engineRef = useRef(new GameEngine());

    const [session, setSession] = useState({
        isPlaying: false,
        winner: null as Team | null,
        timeScale: 1.0,
        isShowcaseMode: false, // 修正：預設關閉展示模式
        transitionPhase: 'IDLE' as 'IDLE' | 'IN' | 'OUT',
        unitCount: 0
    });

    const [editor, setEditor] = useState({
        tool: ToolType.SELECT,
        selectedObstacle: 'WALL',
        hpInput: 600,
        spawnMode: 'RANDOM' as 'RANDOM' | 'DRAFT',
        draftRole: Role.WARRIOR,
        hexLayout: DEFAULT_HEX_LAYOUT,
        mapW: 12,
        mapH: 8,
        currentSceneId: 'VOID'
    });

    const [hud, setHud] = useState({
        selectedAgent: null as Agent | null,
        hoveredSkill: null as Skill | null,
        showLogs: false,
        showDB: false,
        showVFXMap: false,
        showFactionWarning: false,
        showDirectorMonitor: true // 新增：預設開啟導播監測面板
    });

    const internalSpawnTeams = useCallback(() => {
        const engine = engineRef.current;
        let validHexes = Array.from(engine.mapKeys).map(k => {
            const [q, r] = k.split(',').map(Number);
            return {q, r};
        }).filter(h => !engine.map.hasObstacle(h.q, h.r));

        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }

        const roles: Role[] = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];
        let spawnIdx = 0;

        const spawn = (team: Team) => {
            for(let i=0; i<5; i++) {
                if (spawnIdx >= validHexes.length) break;
                const h = validHexes[spawnIdx++];
                engine.addAgent(team, h.q, h.r, 600 + Math.random()*400, roles[i % roles.length]);
            }
        };

        spawn(Team.BLUE); 
        spawn(Team.RED);
        setSession(prev => ({ ...prev, unitCount: engine.agents.length }));
    }, []);

    const setupShowcaseMap = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        engine.clear(true); 
        setHud(prev => ({ ...prev, selectedAgent: null }));
        engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
        engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
        const newLayout: HexLayout = Math.random() > 0.5 ? 'FLAT' : 'POINTY';
        engine.mapConfig.layout = newLayout;
        engine.randomizeEnvironment(); 
        setEditor(prev => ({ ...prev, hexLayout: newLayout, currentSceneId: engine.currentScene.id }));
    }, []);

    useEffect(() => {
        const engine = engineRef.current;
        const handleGameOver = (data: { winner: Team }) => {
            setSession(prev => ({ ...prev, winner: data.winner, isPlaying: false }));
            if (engine.isRunning) engine.stop(); 
        };
        engine.bus.on('GAME_OVER', handleGameOver);
        return () => engine.bus.off('GAME_OVER', handleGameOver);
    }, []);

    const spawnShowcaseUnits = useCallback(() => {
        const engine = engineRef.current;
        internalSpawnTeams();
        engine.play();
        setSession(prev => ({ ...prev, isPlaying: true, winner: null }));
    }, [internalSpawnTeams]);

    useEffect(() => {
        if (session.isShowcaseMode && session.winner !== null) {
            const timer = setTimeout(() => {
                const engine = engineRef.current;
                engine.stop();
                engine.clear(true); 
                setSession(prev => ({ ...prev, transitionPhase: 'OUT' }));
                setTimeout(() => {
                    setupShowcaseMap(); 
                    setSession(prev => ({ ...prev, transitionPhase: 'IN' })); 
                    setTimeout(() => {
                        setSession(prev => ({ ...prev, transitionPhase: 'IDLE' }));
                        spawnShowcaseUnits(); 
                    }, 1500);
                }, 1200);
            }, 2000);
            return () => clearTimeout(timer);
        }
    }, [session.winner, session.isShowcaseMode, setupShowcaseMap, spawnShowcaseUnits]);

    useEffect(() => { 
        if (session.isShowcaseMode) {
            setupShowcaseMap(); 
            spawnShowcaseUnits(); 
        }
    }, []);

    useEffect(() => {
        const interval = setInterval(() => setSession(prev => ({ ...prev, unitCount: engineRef.current.agents.length })), 500);
        return () => clearInterval(interval);
    }, []);

    useEffect(() => { 
        engineRef.current.targetTimeScale = session.timeScale; 
    }, [session.timeScale]);

    const enterManualMode = () => {
        engineRef.current.stop();
        engineRef.current.clear(true);
        setSession(prev => ({ ...prev, isShowcaseMode: false, isPlaying: false, winner: null, unitCount: 0 }));
        setEditor(prev => ({ 
            ...prev, 
            mapW: engineRef.current.mapConfig.w, 
            mapH: engineRef.current.mapConfig.h, 
            hexLayout: engineRef.current.mapConfig.layout, 
            currentSceneId: engineRef.current.currentScene.id 
        }));
    };

    return {
        engineRef,
        state: { 
            isShowcaseMode: session.isShowcaseMode, isPlaying: session.isPlaying, unitCount: session.unitCount, winner: session.winner, timeScale: session.timeScale, transitionPhase: session.transitionPhase,
            tool: editor.tool, selectedObstacle: editor.selectedObstacle, hpInput: editor.hpInput, mapW: editor.mapW, mapH: editor.mapH, currentSceneId: editor.currentSceneId, spawnMode: editor.spawnMode, draftRole: editor.draftRole, hexLayout: editor.hexLayout,
            selectedAgent: hud.selectedAgent, hoveredSkill: hud.hoveredSkill, showLogs: hud.showLogs, showDB: hud.showDB, showVFXMap: hud.showVFXMap, showFactionWarning: hud.showFactionWarning,
            showDirectorMonitor: hud.showDirectorMonitor
        },
        setters: {
            setTool: (tool: ToolType) => setEditor(p => ({...p, tool})),
            setSelectedObstacle: (selectedObstacle: string) => setEditor(p => ({...p, selectedObstacle})),
            setHpInput: (hpInput: number) => setEditor(p => ({...p, hpInput})),
            setTimeScale: (timeScale: number) => setSession(p => ({...p, timeScale})),
            setSpawnMode: (spawnMode: 'RANDOM' | 'DRAFT') => setEditor(p => ({...p, spawnMode})),
            setDraftRole: (draftRole: Role) => setEditor(p => ({...p, draftRole})),
            setShowLogs: (showLogs: boolean) => setHud(p => ({...p, showLogs})),
            setShowDB: (showDB: boolean) => setHud(p => ({...p, showDB})),
            setShowVFXMap: (showVFXMap: boolean) => setHud(p => ({...p, showVFXMap})),
            setIsShowcaseMode: (isShowcaseMode: boolean) => setSession(p => ({...p, isShowcaseMode})),
            setSelectedAgent: (selectedAgent: Agent | null) => setHud(p => ({...p, selectedAgent})),
            setHoveredSkill: (hoveredSkill: Skill | null) => setHud(p => ({...p, hoveredSkill})),
            setShowDirectorMonitor: (v: boolean) => setHud(p => ({...p, showDirectorMonitor: v}))
        },
        actions: {
            enterManualMode,
            handleUpdateMapSize: (w: number, h: number) => { setEditor(p => ({...p, mapW: w, mapH: h})); engineRef.current.mapConfig.w = w; engineRef.current.mapConfig.h = h; engineRef.current.clear(true); },
            handleUpdateLayout: (l: HexLayout) => { setEditor(p => ({...p, hexLayout: l})); engineRef.current.mapConfig.layout = l; engineRef.current.clear(true); },
            handleSetScene: (id: string) => { const s = SCENE_DB.find(x => x.id === id); if(s) { engineRef.current.currentScene = s; engineRef.current.map.rebuildMap(engineRef.current); setEditor(p => ({...p, currentSceneId: id})); } },
            handleRandomBattlefield: () => { 
                engineRef.current.stop(); 
                engineRef.current.clear(true);
                engineRef.current.randomizeEnvironment(); 
                internalSpawnTeams();
                setSession(p => ({...p, winner: null, isPlaying: false})); 
                setEditor(p => ({...p, mapW: engineRef.current.mapConfig.w, mapH: engineRef.current.mapConfig.h, currentSceneId: engineRef.current.currentScene.id})); 
            },
            handleReset: () => { engineRef.current.restart(); setSession(p => ({...p, isPlaying: false, winner: null})); },
            togglePlay: () => { 
                if(session.winner) return;
                if(session.isPlaying) { engineRef.current.stop(); setSession(p => ({...p, isPlaying: false})); }
                else {
                    if(engineRef.current.agents.some(a => a.team === Team.BLUE) && engineRef.current.agents.some(a => a.team === Team.RED)) {
                        engineRef.current.play(); setSession(p => ({...p, isPlaying: true}));
                    } else { setHud(p => ({...p, showFactionWarning: true})); setTimeout(() => setHud(p => ({...p, showFactionWarning: false})), 2500); }
                }
            },
            handleNextLevel: () => { 
                engineRef.current.stop(); 
                engineRef.current.clear(true); 
                engineRef.current.randomizeEnvironment(); 
                internalSpawnTeams(); 
                setSession(p => ({...p, isPlaying: false, winner: null})); 
            },
            rematch: () => { engineRef.current.restart(); engineRef.current.play(); setSession(p => ({...p, isPlaying: true, winner: null})); },
            startShowcaseMatch: () => { setupShowcaseMap(); spawnShowcaseUnits(); },
            downloadSpec: DesignExporter.downloadSpec,
            handleSelectAgent: (a: Agent | null) => setHud(p => ({...p, selectedAgent: a}))
        }
    };
};

import { Agent, GameEngine } from "../game";
import { GridSystem } from "../systems/grid";
import { HexUtils } from "../utils";

export interface RenderCamera {
    x: number;
    y: number;
    zoom: number;
}

export class TacticalRenderer {
    private holoGlitchTimer = 0;
    private lastDirectorTarget = "";

    public update(dt: number, engine: GameEngine) {
        if (engine.directorTargetId !== this.lastDirectorTarget) {
            this.lastDirectorTarget = engine.directorTargetId || "";
            this.holoGlitchTimer = 0.3; 
        }
        if (this.holoGlitchTimer > 0) this.holoGlitchTimer -= dt;
    }

    public drawOverlay(ctx: CanvasRenderingContext2D, engine: GameEngine, highlight: Agent | null, grid: GridSystem, globalTime: number) {
        ctx.save();
        if (highlight && highlight.hp > 0) {
            const hH = grid.getTerrainHeight(highlight.q, highlight.r, engine);
            const startPx = highlight.px;
            const startPy = highlight.py - hH - 30; 
            if (highlight.trajectory.length > 0) {
                ctx.beginPath();
                ctx.moveTo(startPx, startPy);
                highlight.trajectory.forEach(hex => {
                    const p = HexUtils.toPx(hex.q, hex.r, engine.mapConfig);
                    const h = grid.getTerrainHeight(hex.q, hex.r, engine);
                    ctx.lineTo(p.x, p.y - h - 30);
                });
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.setLineDash([5, 5]); 
                ctx.globalAlpha = 0.6;
                ctx.stroke();
                ctx.setLineDash([]); 
                ctx.globalAlpha = 1.0;
                const dest = highlight.trajectory[highlight.trajectory.length - 1];
                const dP = HexUtils.toPx(dest.q, dest.r, engine.mapConfig);
                const dH = grid.getTerrainHeight(dest.q, dest.r, engine);
                ctx.save();
                ctx.translate(dP.x, dP.y - dH);
                ctx.scale(1, 0.6);
                ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); 
                ctx.fillStyle = '#fff'; ctx.globalAlpha = 0.3; ctx.fill();
                ctx.strokeStyle = '#fff'; ctx.globalAlpha = 0.8; ctx.lineWidth=2; ctx.stroke();
                ctx.restore();
            }
            if (highlight.target && highlight.target.hp > 0) {
                const t = highlight.target;
                const tH = grid.getTerrainHeight(t.q, t.r, engine);
                const endPx = t.px;
                const endPy = t.py - tH - 30;
                const grad = ctx.createLinearGradient(startPx, startPy, endPx, endPy);
                const isEnemy = highlight.team !== t.team;
                const color = isEnemy ? '#ef4444' : '#4ade80';
                grad.addColorStop(0, 'rgba(0,0,0,0)'); 
                grad.addColorStop(0.2, color);
                grad.addColorStop(1, color);
                ctx.beginPath();
                ctx.moveTo(startPx, startPy);
                ctx.lineTo(endPx, endPy);
                ctx.strokeStyle = grad;
                ctx.lineWidth = 2;
                ctx.globalAlpha = 0.8 + Math.sin(globalTime * 10) * 0.2; 
                ctx.stroke();
                ctx.globalAlpha = 1.0;
            }
        }
        ctx.restore();
    }

    public drawDebug(ctx: CanvasRenderingContext2D, fps: number): void {
        ctx.fillStyle = 'rgba(255,255,255,0.5)'; 
        ctx.font = '10px monospace';
        ctx.fillText(`FPS: ${fps}`, 10, 20);
    }
}

import React, { useState, useEffect, useRef } from 'react';
import { GameEngine, Agent } from '../../engine/game';
import { Team } from '../../types';
import { useDraggable } from '../../hooks/useDraggable';
import { Icons } from './icons';

interface DirectorMonitorHUDProps {
    engine: GameEngine;
    onClose: () => void;
}

export const DirectorMonitorHUD: React.FC<DirectorMonitorHUDProps> = ({ engine, onClose }) => {
    const [targetAgent, setTargetAgent] = useState<Agent | null>(null);
    const [version, setVersion] = useState(0);
    const ref = useRef<HTMLDivElement>(null);
    const { dragHandlers, style, isDragging } = useDraggable(ref, {
        anchor: 'top-right',
        margin: 20
    });

    useEffect(() => {
        const interval = setInterval(() => {
            const ds = engine.state.director;
            if (ds.targetId) {
                const agent = engine.agents.find(a => a.id === ds.targetId);
                if (agent) {
                    setTargetAgent(agent);
                    setVersion(v => v + 1);
                }
            } else {
                setTargetAgent(null);
            }
        }, 100);
        return () => clearInterval(interval);
    }, [engine]);

    if (!targetAgent) return null;

    const teamColor = targetAgent.team === Team.BLUE ? 'cyan' : 'red';
    const accentColor = targetAgent.team === Team.BLUE ? 'text-cyan-400' : 'text-red-500';
    const borderColor = targetAgent.team === Team.BLUE ? 'border-cyan-500/50' : 'border-red-500/50';
    const glowColor = targetAgent.team === Team.BLUE ? 'rgba(6, 182, 212, 0.4)' : 'rgba(239, 68, 68, 0.4)';

    const nodes = [
        { label: 'SCAN', active: true },
        { label: 'THINK', active: targetAgent.btStatus !== '待機' && targetAgent.btStatus !== 'IDLE' },
        { label: 'ACT', active: targetAgent.isMoving || targetAgent.castingSkillIdx !== -1 }
    ];

    return (
        <div 
            ref={ref}
            style={{...style, width: '280px'}}
            className="z-40 pointer-events-auto"
            {...dragHandlers}
        >
            <div className={`relative p-1 border-2 border-dashed ${borderColor} rounded-2xl transition-all duration-300 ${isDragging ? 'scale-105' : ''}`}>
                <div 
                    className="liquid-card !bg-slate-900/90 !rounded-xl p-5 border border-white/5 backdrop-blur-xl shadow-2xl"
                    style={{ boxShadow: `0 0 30px ${glowColor}` }}
                >
                    <div className="flex justify-between items-start mb-4">
                        <div className="flex flex-col gap-0.5">
                            <span className={`text-[11px] font-black tracking-widest ${accentColor}`}>TARGET: {targetAgent.id}</span>
                            <div className="flex items-center gap-2 mt-1">
                                <span className="text-[10px] font-bold text-slate-500 uppercase">STATUS:</span>
                                <span className="text-[10px] font-mono font-bold text-white uppercase truncate max-w-[120px]">
                                    {targetAgent.btStatus || 'STANDBY'}
                                </span>
                            </div>
                        </div>
                        <button 
                            onClick={onClose}
                            className="text-slate-500 hover:text-white transition-colors"
                        >
                            <Icons.Close className="w-3 h-3" />
                        </button>
                    </div>

                    <div className="relative h-12 flex items-center justify-between px-4 mt-6">
                        <div className="absolute left-6 right-6 h-0.5 bg-white/10 top-1/2 -translate-y-1/2"></div>

                        {nodes[1].active && (
                            <div className="absolute left-6 right-6 h-0.5 top-1/2 -translate-y-1/2 overflow-hidden pointer-events-none">
                                <div className="h-full w-4 bg-white/40 blur-sm animate-[flow_2s_linear_infinite]"></div>
                            </div>
                        )}

                        {nodes.map((n, i) => (
                            <div key={n.label} className="relative flex flex-col items-center z-10">
                                <div className={`w-4 h-4 rounded-full border-2 transition-all duration-300 flex items-center justify-center
                                    ${n.active ? `bg-${teamColor}-500 border-${teamColor}-400 shadow-[0_0_10px_${glowColor}]` : 'bg-slate-800 border-slate-700'}`}>
                                    {n.active && <div className="w-1.5 h-1.5 rounded-full bg-white animate-pulse"></div>}
                                </div>
                                <span className={`text-[9px] font-black mt-2 tracking-tighter ${n.active ? 'text-white' : 'text-slate-600'}`}>{n.label}</span>
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            <style>{`
                @keyframes flow {
                    0% { transform: translateX(-100%); }
                    100% { transform: translateX(400%); }
                }
            `}</style>
        </div>
    );
};

import React from 'react';
import GameCanvas from './components/GameCanvas';
import { ShowcaseOverlay } from './components/ui/showcase/ShowcaseOverlay';
import { PlaybackHUD } from './components/ui/PlaybackHUD';
import { MapEditorToolbar } from './components/ui/MapEditorToolbar';
import { UnitInspectorHUD } from './components/ui/UnitInspectorHUD';
import { DirectorMonitorHUD } from './components/ui/DirectorMonitorHUD'; // 新增
